    return this.read<string[]>(key, [], (entry) => entry.metadata.tags ?? []);
  }

  async getMetadata(key: string): Promise<EntryMetadata | undefined> {
    return this.read<EntryMetadata | undefined>(key, undefined, (entry) => entry.metadata);
  }
}

