@dataclass
class Bot:
    """Meeting bot entity."""

    id: str
    namespace: str
    meeting_url: str
    platform: str
    status: str
    config: Dict[str, Any]
    error_message: Optional[str] = None
    created_at: str = ""
    updated_at: str = ""


@dataclass
class AggregateBotDetail(Bot):
    """Aggregate bot detail including nested related resources."""

    participants: List["Participant"] = None
    recordings: List["Recording"] = None
