"""Threaded batching with shared pending state and serialized delivery."""

import math
import threading
import time
from collections import deque
from typing import Any, Callable, List


class Batcher:
    def __init__(self, on_flush: Callable[[List[Any]], Any], max_size=100, max_wait=5.0):
        if (isinstance(max_size, bool) or not isinstance(max_size, int) or max_size <= 0
                or not math.isfinite(max_wait) or max_wait <= 0):
            raise ValueError("Batch size and wait must be positive")
        self.on_flush = on_flush
        self.max_size = max_size
        self.max_wait = max_wait
        self._pending = deque()
        self._condition = threading.Condition()
        self._delivery = threading.Lock()
        self._stopped = True
        self._thread = None

    def start(self):
        with self._condition:
            if self._thread is not None:
                return
            self._stopped = False
            self._thread = threading.Thread(target=self._run, daemon=True)
            self._thread.start()

    def stop(self):
        with self._condition:
            self._stopped = True
            self._condition.notify_all()
            thread = self._thread
        if thread is not None:
            thread.join()
        with self._condition:
            self._thread = None
        self.flush()

    def add(self, item: Any):
        with self._condition:
            self._pending.append(item)
            self._condition.notify_all()

    def _run(self):
        deadline = time.monotonic() + self.max_wait
        while True:
            with self._condition:
                while not self._stopped:
                    remaining = deadline - time.monotonic()
                    if len(self._pending) >= self.max_size or remaining <= 0:
                        break
                    self._condition.wait(remaining)
                if self._stopped:
                    return
            try:
                self.flush()
            except Exception:
                # Pending events are restored; explicit flush/stop surfaces errors.
                # Back off even when the size threshold remains exceeded.
                with self._condition:
                    self._condition.wait_for(lambda: self._stopped, self.max_wait)
            deadline = time.monotonic() + self.max_wait

    def flush_batch(self, batch):
        if batch:
            self.on_flush(batch)

    def flush(self):
        # A query/stop waits for any active delivery before reading storage.
        with self._delivery:
            with self._condition:
                count = len(self._pending)
            while count:
                with self._condition:
                    batch = [self._pending.popleft() for _ in range(min(count, self.max_size))]
                try:
                    self.flush_batch(batch)
                except BaseException:
                    with self._condition:
                        self._pending.extendleft(reversed(batch))
                    raise
                count -= len(batch)
"""Metric aggregation for real-time analytics."""

from typing import Dict, List, Optional, Literal
from dataclasses import dataclass
import time


AggregationInterval = Literal["1m", "5m", "15m", "1h", "6h", "1d"]
AggregationFunction = Literal["count", "sum", "avg", "min", "max", "p50", "p75", "p90", "p95", "p99"]


@dataclass
class MetricPoint:
    timestamp: float
    value: float
    tags: Optional[Dict[str, str]] = None


@dataclass
class AggregatedMetric:
    metric: str
    interval: str
    timestamp: float
    value: float
    function: str
    tags: Optional[Dict[str, str]] = None


class MetricAggregator:
    """Real-time metric aggregation with rolling windows."""

    def __init__(
        self,
        intervals: List[AggregationInterval] = None,
        functions: List[AggregationFunction] = None,
        window_size: int = 1000
    ):
        self.intervals = intervals or ["1m", "5m", "1h"]
        self.functions = functions or ["count", "avg", "p95"]
        self.window_size = window_size
        self.windows: Dict[str, Dict[str, List]] = {}  # metric -> {values, timestamps}
        self.aggregations: Dict[str, Dict[tuple, AggregatedMetric]] = {}

    def add(self, metric: str, point: MetricPoint) -> None:
        """Add a metric point and update rolling windows."""
        key = self._get_window_key(metric, point.tags)

        if key not in self.windows:
            self.windows[key] = {"values": [], "timestamps": []}

        window = self.windows[key]
        window["values"].append(point.value)
        window["timestamps"].append(point.timestamp)

        # Keep window size in check
        if len(window["values"]) > self.window_size:
            window["values"].pop(0)
            window["timestamps"].pop(0)

        # Trigger aggregation for configured intervals
        for interval in self.intervals:
            self._aggregate_window(metric, interval, point.timestamp, point.tags)

    def get(
        self,
        metric: str,
        interval: AggregationInterval,
        from_time: float,
        to_time: float,
        function: Optional[AggregationFunction] = None,
        tags: Optional[Dict[str, str]] = None
    ) -> List[AggregatedMetric]:
        """Get aggregated metrics for a time range."""
        key = self._get_aggregation_key(metric, interval, tags)
        aggs = self.aggregations.get(key, {})

        results = []
        for agg in aggs.values():
            if agg.timestamp + self._get_interval_ms(interval) > from_time and agg.timestamp <= to_time:
                if function is None or agg.function == function:
                    results.append(agg)

        return sorted(results, key=lambda x: x.timestamp)

    def prune(self, retention_ms: float) -> None:
        """Clear old aggregations based on retention."""
        cutoff = time.time() * 1000 - retention_ms

        for key in list(self.aggregations.keys()):
            aggs = self.aggregations[key]
            to_delete = [key for key, agg in aggs.items() if agg.timestamp < cutoff]
            for ts in to_delete:
                del aggs[ts]

            if not aggs:
                del self.aggregations[key]

        # Prune rolling windows
        for key in list(self.windows.keys()):
            window = self.windows[key]
            valid_indices = [i for i, ts in enumerate(window["timestamps"]) if ts >= cutoff]

            if not valid_indices:
                del self.windows[key]
            elif len(valid_indices) < len(window["timestamps"]):
                window["values"] = [window["values"][i] for i in valid_indices]
                window["timestamps"] = [window["timestamps"][i] for i in valid_indices]

    def _aggregate_window(
        self,
        metric: str,
        interval: AggregationInterval,
        timestamp: float,
        tags: Optional[Dict[str, str]] = None
    ) -> None:
        """Aggregate window for a specific interval."""
        interval_ms = self._get_interval_ms(interval)
        bucket_timestamp = (int(timestamp) // interval_ms) * interval_ms

        window_key = self._get_window_key(metric, tags)
        if window_key not in self.windows:
            return

        window = self.windows[window_key]
        if not window["values"]:
            return

        # Get values within this interval bucket
        bucket_values = [
            window["values"][i]
            for i, ts in enumerate(window["timestamps"])
            if bucket_timestamp <= ts < bucket_timestamp + interval_ms
        ]

        if not bucket_values:
            return

        # Calculate each aggregation function
        for func in self.functions:
            value = self._calculate_aggregation(bucket_values, func)
            agg_key = self._get_aggregation_key(metric, interval, tags)

            if agg_key not in self.aggregations:
                self.aggregations[agg_key] = {}

            self.aggregations[agg_key][(bucket_timestamp, func)] = AggregatedMetric(
                metric=metric,
                interval=interval,
                timestamp=bucket_timestamp,
                value=value,
                function=func,
                tags=tags
            )

    def _calculate_aggregation(self, values: List[float], func: AggregationFunction) -> float:
        """Calculate aggregation function."""
        if not values:
            return 0.0

        if func == "count":
            return float(len(values))
        elif func == "sum":
            return sum(values)
        elif func == "avg":
            return sum(values) / len(values)
        elif func == "min":
            return min(values)
        elif func == "max":
            return max(values)
        elif func in ["p50", "p75", "p90", "p95", "p99"]:
            p = int(func[1:])
            return self._percentile(values, p)
        return 0.0

    def _percentile(self, values: List[float], p: int) -> float:
        """Calculate percentile."""
        sorted_values = sorted(values)
        index = (p / 100) * (len(sorted_values) - 1)
        lower = int(index)
        upper = min(lower + 1, len(sorted_values) - 1)
        weight = index - lower

        if lower == upper:
            return sorted_values[lower]

        return sorted_values[lower] * (1 - weight) + sorted_values[upper] * weight

    def _get_interval_ms(self, interval: AggregationInterval) -> int:
        """Get interval duration in milliseconds."""
        intervals = {
            "1m": 60 * 1000,
            "5m": 5 * 60 * 1000,
            "15m": 15 * 60 * 1000,
            "1h": 60 * 60 * 1000,
            "6h": 6 * 60 * 60 * 1000,
            "1d": 24 * 60 * 60 * 1000,
        }
        return intervals[interval]

    def _get_window_key(self, metric: str, tags: Optional[Dict[str, str]]) -> str:
        """Get window key for metric and tags."""
        if tags:
            import json
            return f"{metric}:{json.dumps(tags, sort_keys=True)}"
        return metric

    def _get_aggregation_key(self, metric: str, interval: str, tags: Optional[Dict[str, str]]) -> str:
        """Get aggregation key."""
        if tags:
            import json
            return f"{metric}:{interval}:{json.dumps(tags, sort_keys=True)}"
        return f"{metric}:{interval}"
"""Context management for request/user tracking."""

from contextvars import ContextVar
from typing import Any, Dict, Optional
from dataclasses import dataclass, field
import time
import inspect


@dataclass
class Context:
    """Request/user context."""
    request_id: Optional[str] = None
    trace_id: Optional[str] = None
    span_id: Optional[str] = None
    user_id: Optional[str] = None
    session_id: Optional[str] = None
    tags: Dict[str, str] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class ContextStore:
    """Context with start time."""
    context: Context
    start_time: float


# Context variable for async context storage
_context_var: ContextVar[Optional[ContextStore]] = ContextVar("watchfn_context", default=None)


class ContextManager:
    """Manage request and user context using contextvars."""

    def __init__(self):
        self.global_context = Context()

    def run(self, context: Context, func, *args, **kwargs):
        """Run a function with a new context."""
        store = ContextStore(
            context=Context(**{**vars(self.global_context), **vars(context)}),
            start_time=time.time()
        )

