  try {
    bytes = Buffer.from(input.bytesBase64, "base64");
    if (bytes.length === 0 && input.bytesBase64.length > 0) {
      return err("VALIDATION_FAILED", "Invalid base64 encoding", { path: "bytesBase64" });
    }
  } catch {
    return err("VALIDATION_FAILED", "Invalid base64 encoding", { path: "bytesBase64" });
  }

