  input: {
    dataset: string;
    limit?: number;
    offset?: number;
  }
): Promise<ContentfnEnvelope<{ assets: AssetListItem[] }>> {
  const exists = await datasetExists({ db: config.db }, input.dataset);
  if (!exists) {
