    assetId: string;
    url: string;
    filename: string;
    contentType: string;
    size: number;
    createdAt: string;
  }>).map((r) => ({
    assetId: r.assetId,
    url: r.url,
    filename: r.filename,
    contentType: r.contentType,
    size: r.size,
    createdAt: r.createdAt,
  }));

