  const rows = await config.db.findMany({
    model: CONTENTFN_TABLE_NAMES.assets,
    where: [{ field: "dataset", operator: "eq" as const, value: input.dataset }],
    orderBy: [
      { field: "createdAt", direction: "desc" },
      { field: "assetId", direction: "asc" },
    ],
