/**
 * Preview token minting: short-lived, dataset/doc-bound, signed with server secret.
 */

import { createHmac } from "node:crypto";
import type { CmsfnPreviewTokenResult } from "cmsfn";

const DEFAULT_TTL_SEC = 60 * 15; // 15 minutes
const TOKEN_SEP = ".";

export interface MintPreviewTokenConfig {
  /** Secret for HMAC signing; required for minting. */
  secret: string;
  /** Token TTL in seconds. */
  ttlSec?: number;
}

/**
 * Mint a preview token bound to dataset and docIds. Deterministic expiry from now + ttlSec.
 */
export function mintPreviewToken(
  config: MintPreviewTokenConfig,
  dataset: string,
  docIds: string[]
): CmsfnPreviewTokenResult {
  const ttlSec = config.ttlSec ?? DEFAULT_TTL_SEC;
  const exp = Math.floor(Date.now() / 1000) + ttlSec;
  const payload = JSON.stringify({ dataset, docIds, exp });
  const payloadB64 = Buffer.from(payload, "utf8").toString("base64url");
  const sig = createHmac("sha256", config.secret).update(payloadB64).digest("base64url");
  const token = `${payloadB64}${TOKEN_SEP}${sig}`;
  const expiresAt = new Date(exp * 1000).toISOString();
  return { token, expiresAt, dataset, docIds };
}

/**
 * Verify and decode a token. Returns payload or null if invalid/expired.
 */
export function verifyPreviewToken(
  secret: string,
  token: string
): { dataset: string; docIds: string[]; exp: number } | null {
  const i = token.indexOf(TOKEN_SEP);
  if (i <= 0) return null;
  const payloadB64 = token.slice(0, i);
  const sig = token.slice(i + 1);
  const expectedSig = createHmac("sha256", secret).update(payloadB64).digest("base64url");
  if (sig !== expectedSig) return null;
  let payload: unknown;
  try {
    payload = JSON.parse(Buffer.from(payloadB64, "base64url").toString("utf8"));
  } catch {
    return null;
  }
  const o = payload as Record<string, unknown>;
  if (typeof o.dataset !== "string" || !Array.isArray(o.docIds) || typeof o.exp !== "number") return null;
  if (o.exp < Math.floor(Date.now() / 1000)) return null;
  return { dataset: o.dataset, docIds: o.docIds as string[], exp: o.exp };
}
/**
 * POST /cmsfn/preview/token — mint short-lived preview token (dataset + docIds bound).
 */

import type { IncomingMessage } from "http";
import type { CmsfnEnvelope, CmsfnPreviewTokenResult } from "cmsfn";
import { ok, err } from "cmsfn";
import { authorize } from "../auth/authorize.js";
import type { AuthorizeConfig } from "../auth/authorize.js";
import { mintPreviewToken } from "../preview/tokens.js";

export interface PreviewTokenHandlerConfig extends AuthorizeConfig {
  /** When false or unset, return PREVIEW_NOT_CONFIGURED. */
  previewEnabled?: boolean;
  /** Secret for signing tokens; required when preview enabled. */
  previewSecret?: string;
  ttlSec?: number;
}

async function parseJsonBody(req: IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) {
    chunks.push(typeof chunk === "string" ? Buffer.from(chunk) : chunk);
  }
  const raw = Buffer.concat(chunks).toString("utf8");
  if (!raw.trim()) return {};
  try {
    return JSON.parse(raw);
  } catch {
    return {};
  }
}

/**
 * Handle POST /cmsfn/preview/token.
 * Body: { dataset: string; docId?: string; docIds?: string[] }.
 * Accepts docId (single) or docIds (array); normalizes to docIds.
 */
export async function handlePreviewToken(
  config: PreviewTokenHandlerConfig,
  req: IncomingMessage
): Promise<CmsfnEnvelope<CmsfnPreviewTokenResult>> {
  if (!config.previewEnabled || !config.previewSecret) {
    return err("PREVIEW_NOT_CONFIGURED", "Preview is not configured", {});
  }

  const body = (await parseJsonBody(req)) as Record<string, unknown>;
  const dataset = body?.dataset;
  if (typeof dataset !== "string" || dataset.trim().length === 0) {
    return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  }
  const ds = dataset.trim();

  let docIds: string[];
  if (Array.isArray(body?.docIds) && body.docIds.every((id: unknown) => typeof id === "string")) {
    docIds = (body.docIds as string[]).map((id) => String(id).trim()).filter(Boolean);
  } else if (typeof body?.docId === "string" && body.docId.trim().length > 0) {
    docIds = [body.docId.trim()];
  } else {
    docIds = [];
  }

  const allowed = await authorize(config, req, {
    dataset: ds,
    type: "*",
    action: "doc.read",
  });
  if (!allowed) {
    return err("PERMISSION_DENIED", "Permission denied", {});
  }

  const result = mintPreviewToken(
    { secret: config.previewSecret, ttlSec: config.ttlSec },
    ds,
    docIds
  );
  return ok(result);
}
/**
 * ContentFn status client: fetches /contentfn/status and verifies required capabilities.
 * Used by CmsFn status endpoint to fail with CONTENTFN_UNAVAILABLE when unreachable or missing caps.
 */

/** Required capabilities when preview is disabled. */
const REQUIRED_CAPABILITIES = [
  "content.schema",
  "content.docs",
  "content.assets",
] as const;

/** Additional capability when preview is enabled. */
const REALTIME_CAPABILITY = "content.realtime";

export interface ContentfnStatusResult {
  serverTime: string;
  capabilities: string[];
}

/**
 * Deterministically parse ContentFn status response.
 * Expects envelope shape: { ok: true, result: { serverTime, capabilities, limits? } }.
 */
function parseContentfnStatusResponse(body: string): ContentfnStatusResult | null {
  let data: unknown;
  try {
    data = JSON.parse(body);
  } catch {
    return null;
  }
  if (typeof data !== "object" || data === null) return null;
  const obj = data as Record<string, unknown>;
  if (obj.ok !== true || typeof obj.result !== "object" || obj.result === null)
    return null;
  const result = obj.result as Record<string, unknown>;
  const serverTime = result.serverTime;
  const capabilities = result.capabilities;
  if (typeof serverTime !== "string") return null;
  if (!Array.isArray(capabilities) || !capabilities.every((c) => typeof c === "string"))
    return null;
  return { serverTime, capabilities: capabilities as string[] };
}

/**
 * Fetch ContentFn status and verify required capabilities.
 * Returns the parsed result when reachable and capabilities are satisfied;
 * returns null when unreachable, parse error, or missing required capability.
 *
 * @param baseUrl - ContentFn base URL (e.g. "http://localhost:3000")
 * @param requireRealtime - When true, "content.realtime" must be present (preview enabled).
 */
export async function fetchContentfnStatus(
  baseUrl: string,
  requireRealtime: boolean
): Promise<ContentfnStatusResult | null> {
  const normalizedBase = baseUrl.replace(/\/+$/, "");
  const url = `${normalizedBase}/contentfn/status`;

  let response: Response;
  try {
    response = await fetch(url, { method: "GET" });
  } catch {
    return null;
  }

  if (!response.ok) return null;

  const text = await response.text();
  const parsed = parseContentfnStatusResponse(text);
  if (!parsed) return null;

  const required: string[] = [...REQUIRED_CAPABILITIES];
  if (requireRealtime) required.push(REALTIME_CAPABILITY);

  for (const cap of required) {
    if (!parsed.capabilities.includes(cap)) return null;
  }

  return parsed;
}
/**
 * CmsFn release storage via @superfunctions/db adapter.
 * Table: cmsfn_releases (releaseId, dataset, name, publishAt, docIds, createdAt, updatedAt).
 * List order: createdAt desc, releaseId asc.
 */

import type { Adapter } from "@superfunctions/db";
import { cmsfnStorageAdapter } from "./schema.js";
import type { CmsfnEnvelope, CmsfnRelease } from "cmsfn";
import { ok, err } from "cmsfn";
import { randomUUID } from "node:crypto";
import { MAX_DOCS_PER_RELEASE } from "../limits/limits.js";

export const CMSFN_RELEASES_TABLE = "cmsfn_releases";

export interface ReleasesStorageConfig {
  db: Adapter;
}

interface ReleaseRow {
  releaseId: string;
  dataset: string;
  name: string;
  publishAt: string | null;
  docIds: string[];
  createdAt: string;
  updatedAt: string;
}

function nowIso(): string {
  return new Date().toISOString();
}

/**
 * Create a release. Returns releaseId.
 */
export async function createRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; name: string; publishAt?: string | null }
): Promise<CmsfnEnvelope<{ releaseId: string }>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const name = typeof input.name === "string" ? input.name.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  if (!name) return err("VALIDATION_FAILED", "name is required", { path: "name" });
  const publishAt =
    input.publishAt === undefined || input.publishAt === null
      ? null
      : typeof input.publishAt === "string"
        ? input.publishAt.trim() || null
        : null;

  const releaseId = randomUUID();
  const now = nowIso();
  const row: ReleaseRow = {
    releaseId,
    dataset,
    name,
    publishAt,
    docIds: [],
    createdAt: now,
    updatedAt: now,
  };
  await cmsfnStorageAdapter(config.db).create({
    model: CMSFN_RELEASES_TABLE,
    data: row,
  });
  return ok({ releaseId });
}

/**
 * List releases for dataset. Order: createdAt desc, releaseId asc.
 */
export async function listReleases(
  config: ReleasesStorageConfig,
  input: { dataset: string }
): Promise<CmsfnEnvelope<{ releases: CmsfnRelease[] }>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });

  const rows = await cmsfnStorageAdapter(config.db).findMany({
    model: CMSFN_RELEASES_TABLE,
    where: [{ field: "dataset", operator: "eq", value: dataset }],
    orderBy: [
      { field: "createdAt", direction: "desc" },
      { field: "releaseId", direction: "asc" },
    ],
  });
  const releases: CmsfnRelease[] = (rows as ReleaseRow[]).map((r) => ({
    releaseId: r.releaseId,
    dataset: r.dataset,
    name: r.name,
    publishAt: r.publishAt,
    docIds: Array.isArray(r.docIds) ? r.docIds : [],
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
  }));
  return ok({ releases });
}

/**
 * Get one release by dataset and releaseId.
 */
export async function getRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; releaseId: string }
): Promise<CmsfnRelease | null> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const releaseId = typeof input.releaseId === "string" ? input.releaseId.trim() : "";
  if (!dataset || !releaseId) return null;

  const row = await cmsfnStorageAdapter(config.db).findOne({
    model: CMSFN_RELEASES_TABLE,
    where: [
      { field: "dataset", operator: "eq", value: dataset },
      { field: "releaseId", operator: "eq", value: releaseId },
    ],
  });
  if (!row || typeof row !== "object") return null;
  const r = row as ReleaseRow;
  return {
    releaseId: r.releaseId,
    dataset: r.dataset,
    name: r.name,
    publishAt: r.publishAt,
    docIds: Array.isArray(r.docIds) ? r.docIds : [],
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
  };
}

/**
 * Add a doc to a release. Rejects if release not found or docIds would exceed max.
 */
export async function addDocToRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; releaseId: string; docId: string }
): Promise<CmsfnEnvelope<Record<string, never>>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const releaseId = typeof input.releaseId === "string" ? input.releaseId.trim() : "";
  const docId = typeof input.docId === "string" ? input.docId.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  if (!releaseId) return err("VALIDATION_FAILED", "releaseId is required", { path: "releaseId" });
  if (!docId) return err("VALIDATION_FAILED", "docId is required", { path: "docId" });

  const release = await getRelease(config, { dataset, releaseId });
  if (!release) return err("NOT_FOUND", "Release not found", { releaseId });

  const docIds = [...release.docIds];
  if (docIds.includes(docId)) return ok({});
  if (docIds.length >= MAX_DOCS_PER_RELEASE) {
    return err("VALIDATION_FAILED", "Release has reached max document count", {
      path: "docId",
      limit: MAX_DOCS_PER_RELEASE,
    });
  }
  docIds.push(docId);
  docIds.sort();

  await cmsfnStorageAdapter(config.db).update({
    model: CMSFN_RELEASES_TABLE,
    where: [
      { field: "dataset", operator: "eq", value: dataset },
      { field: "releaseId", operator: "eq", value: releaseId },
    ],
    data: { docIds, updatedAt: nowIso() },
  });
  return ok({});
}
/**
 * Publish a release: for each doc (sorted), check permission + workflow gate, call ContentFn publish.
 * Returns deterministic summary: published[], failures[].
 */

import type { IncomingMessage } from "http";
import { ok } from "cmsfn";
import { CMS_RESERVED_FIELD } from "cmsfn";
import type { CmsfnWorkflowMetadata, CmsfnReleasePublishResult, CmsfnEnvelope } from "cmsfn";
import { authorize } from "../auth/authorize.js";
import type { AuthorizeConfig } from "../auth/authorize.js";
import { canPublish } from "../publish/gates.js";
import { getDraftDoc, contentfnPublish } from "../publish/contentfnClient.js";
import { getRelease } from "../storage/releases.js";
import type { ReleasesStorageConfig } from "../storage/releases.js";

export interface PublishReleaseConfig extends AuthorizeConfig {
  contentfnBaseUrl: string;
  releasesStorage: ReleasesStorageConfig;
}

function getWorkflowState(doc: Record<string, unknown>): string | undefined {
  const cms = doc[CMS_RESERVED_FIELD] as CmsfnWorkflowMetadata | undefined;
  return cms?.state;
}

/**
 * Publish all docs in a release. Doc order: sorted docIds (deterministic).
 * For each doc: check doc.publish for doc's _type, workflow gate, then ContentFn publish.
 * Returns { releaseId, published, failures }.
 */
export async function publishRelease(
  config: PublishReleaseConfig,
  req: IncomingMessage,
  input: { dataset: string; releaseId: string }
): Promise<CmsfnEnvelope<CmsfnReleasePublishResult>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const releaseId = typeof input.releaseId === "string" ? input.releaseId.trim() : "";
  if (!dataset) return { ok: false, error: { code: "VALIDATION_FAILED", message: "dataset is required", details: { path: "dataset" } } };
  if (!releaseId) return { ok: false, error: { code: "VALIDATION_FAILED", message: "releaseId is required", details: { path: "releaseId" } } };

  const release = await getRelease(config.releasesStorage, { dataset, releaseId });
  if (!release) return { ok: false, error: { code: "NOT_FOUND", message: "Release not found", details: { releaseId } } };

  const docIds = [...release.docIds].sort();
  const published: string[] = [];
  const failures: Array<{ docId: string; code: string; message: string }> = [];

  const contentfn = { baseUrl: config.contentfnBaseUrl };

  for (const docId of docIds) {
    const draftRes = await getDraftDoc(contentfn, dataset, docId);
    if (!draftRes.ok) {
      failures.push({
        docId,
        code: draftRes.error.code,
        message: draftRes.error.message,
      });
      continue;
    }
    const draftDoc = draftRes.result as Record<string, unknown>;
    const docType = (draftDoc._type as string) ?? "*";
    const state = getWorkflowState(draftDoc);

    const hasDocPublish = await authorize(config, req, {
      dataset,
      type: docType,
      action: "doc.publish",
    });
    if (!hasDocPublish) {
      failures.push({ docId, code: "PERMISSION_DENIED", message: "Permission denied" });
      continue;
    }
    if (!canPublish(state as "draft" | "in_review" | "approved" | "published", true)) {
      failures.push({
        docId,
        code: "PERMISSION_DENIED",
        message: "Workflow state does not allow publish",
      });
      continue;
    }

    const pubRes = await contentfnPublish(contentfn, dataset, docId);
    if (pubRes.ok) {
      published.push(docId);
    } else {
      failures.push({
        docId,
        code: pubRes.error.code,
        message: pubRes.error.message,
      });
    }
  }

  return ok({
    releaseId,
    published,
    failures,
  });
}
/**
