async function route(
  config: CmsfnServerConfig,
  req: IncomingMessage,
  res: ServerResponse
): Promise<void> {
  const method = req.method ?? "";
  const path = req.url?.split("?")[0] ?? "";

  if (path === "/cmsfn/status" && method === "GET") {
    const envelope = await handleStatus(
