import { randomUUID } from "node:crypto";
import { err, ok, type ContentfnEnvelope } from "@contentfn/core";
import type { ContentfnDatabase } from "./database.js";

export const AUDIT_TABLE = "contentfn_audit";
import type { AuditRecord } from "@contentfn/core";
export type { AuditRecord, AuditQuery } from "@contentfn/core";

/** Called inside the mutation transaction. Never persist input bodies or credentials. */
export async function appendAudit(db: ContentfnDatabase, action: string, input: Record<string, unknown>, result: unknown, subject?: string): Promise<void> {
  const output = result && typeof result === "object" ? result as Record<string, unknown> : {};
  const ids: unknown[] = [input.dataset];
  if (action.startsWith("docs.")) ids.push(output._id ?? input.id);
  if (action === "docs.schedule") ids.push(output.scheduleId);
  if (action === "assets.upload") ids.push(output.assetId);
  if (action === "webhooks.register") ids.push(output.webhookId);
  if (action === "webhooks.delete") ids.push(input.webhookId);
  await db.create({ model: AUDIT_TABLE, data: {
    id: randomUUID(), dataset: String(input.dataset ?? ""), action,
    actor: subject === undefined ? null : { subject },
    targetIds: [...new Set(ids.filter((value): value is string => typeof value === "string"))],
    timestamp: new Date().toISOString(),
  } });
}

export async function queryAudit(config: { db: ContentfnDatabase }, input: unknown): Promise<ContentfnEnvelope<{ records: AuditRecord[]; nextOffset: number | null }>> {
  const value = input as Record<string, unknown> | null;
  if (!value || typeof value.dataset !== "string" || !value.dataset || (value.action !== undefined && typeof value.action !== "string")) return err("VALIDATION_FAILED", "dataset and an optional action string are required", {});
  if (value.order !== undefined && value.order !== "asc" && value.order !== "desc") return err("VALIDATION_FAILED", "order must be asc or desc", {});
  const limit = value.limit ?? 100, offset = value.offset ?? 0;
  if (!Number.isSafeInteger(limit) || (limit as number) < 1 || (limit as number) > 1000 || !Number.isSafeInteger(offset) || (offset as number) < 0 || (offset as number) > Number.MAX_SAFE_INTEGER - 1001) return err("VALIDATION_FAILED", "limit must be 1 to 1000 and offset a nonnegative safe integer", {});
  const rows = await config.db.findMany({ model: AUDIT_TABLE,
    where: [{ field: "dataset", operator: "eq", value: value.dataset }, ...(value.action === undefined ? [] : [{ field: "action", operator: "eq" as const, value: value.action }])],
    orderBy: [{ field: "timestamp", direction: value.order ?? "asc" }, { field: "id", direction: "asc" }],
    limit: (limit as number) + 1, offset: offset as number,
  });
  return ok({ records: rows.slice(0, limit as number) as unknown as AuditRecord[], nextOffset: rows.length > (limit as number) ? (offset as number) + (limit as number) : null });
}
import type { Adapter, TransactionAdapter } from "@superfunctions/db";
import type { ContentfnEnvelope } from "@contentfn/core";
import { err } from "@contentfn/core";

export type ContentfnDatabase = Adapter | TransactionAdapter;
class AbortedMutation<T> extends Error {
  constructor(readonly result: ContentfnEnvelope<T>) { super("Content mutation aborted"); }
}

/** All related writes commit together, including revision and durable event records. */
export async function atomicMutation<T>(
  db: Adapter,
  operation: (transaction: TransactionAdapter) => Promise<ContentfnEnvelope<T>>,
): Promise<ContentfnEnvelope<T>> {
  try {
    return await db.transaction(async transaction => {
      // Some adapters retain root-only methods on their runtime transaction object.
      // Hide these at the function boundary so nested storage calls reuse this transaction.
      const scoped = new Proxy(transaction, {
        has: (target, key) => key !== "transaction" && key !== "close" && Reflect.has(target, key),
        get: (target, key) => key === "transaction" || key === "close" ? undefined : Reflect.get(target, key),
      });
      const result = await operation(scoped);
      if (!result.ok) throw new AbortedMutation(result);
      return result;
    });
  } catch (error) {
    if (error instanceof AbortedMutation) return error.result as ContentfnEnvelope<T>;
    return err("STORAGE_ERROR", "The content transaction could not be completed", {});
  }
}
import type { ContentfnDatabase as Adapter } from "./database.js";
import { enqueueWebhookDelivery } from "./webhookQueue.js";
import { nowISO } from "../time/clock.js";
import { CONTENTFN_TABLE_NAMES } from "./schema.js";

export interface EventsStorageConfig {
  db: Adapter;
  actor?: { subject: string };
}

export interface ContentfnEvent {
  eventId: string;
  dataset: string;
  type: string;
  timestamp: string;
  actor?: { subject: string };
  docId?: string;
  rev?: string;
  changedPaths?: string[];
}

function generateEventId(): string {
  return `evt_${Date.now()}_${Math.random().toString(36).substring(2, 12)}`;
}

export async function appendEvent(
  config: EventsStorageConfig,
  input: {
    dataset: string;
    type: string;
    actor?: { subject: string };
    docId?: string;
    rev?: string;
    changedPaths?: string[];
  }
): Promise<ContentfnEvent> {
  const actor = input.actor ?? config.actor;
  const eventId = generateEventId();
  const timestamp = nowISO();

  const event: ContentfnEvent = {
    eventId,
    dataset: input.dataset,
    type: input.type,
    timestamp,
    actor,
    docId: input.docId,
    rev: input.rev,
    changedPaths: input.changedPaths || [],
  };

  await config.db.create({
    model: CONTENTFN_TABLE_NAMES.events,
    data: {
      id: eventId,
      eventId,
      dataset: input.dataset,
      type: input.type,
      timestamp,
      actor: actor || null,
      docId: input.docId || null,
      rev: input.rev || null,
      changedPaths: input.changedPaths || [],
    },
  });

  const hooks = await config.db.findMany({ model: CONTENTFN_TABLE_NAMES.webhooks, where: [{ field: "dataset", operator: "eq", value: input.dataset }] });
  for (const hook of hooks) {
    if (Array.isArray(hook.events) && hook.events.includes(input.type)) {
      await enqueueWebhookDelivery(config, { eventId, webhookId: hook.webhookId as string });
    }
  }
