import type { Adapter, TransactionAdapter } from "@superfunctions/db";
import type { ContentfnEnvelope } from "@contentfn/core";
import { err } from "@contentfn/core";

export type ContentfnDatabase = Adapter | TransactionAdapter;
class AbortedMutation<T> extends Error {
  constructor(readonly result: ContentfnEnvelope<T>) { super("Content mutation aborted"); }
}

/** All related writes commit together, including revision and durable event records. */
export async function atomicMutation<T>(
  db: Adapter,
  operation: (transaction: TransactionAdapter) => Promise<ContentfnEnvelope<T>>,
): Promise<ContentfnEnvelope<T>> {
  try {
    return await db.transaction(async transaction => {
      // Some adapters retain root-only methods on their runtime transaction object.
      // Hide these at the function boundary so nested storage calls reuse this transaction.
      const scoped = new Proxy(transaction, {
        has: (target, key) => key !== "transaction" && key !== "close" && Reflect.has(target, key),
        get: (target, key) => key === "transaction" || key === "close" ? undefined : Reflect.get(target, key),
      });
      const result = await operation(scoped);
      if (!result.ok) throw new AbortedMutation(result);
      return result;
    });
  } catch (error) {
    if (error instanceof AbortedMutation) return error.result as ContentfnEnvelope<T>;
    return err("STORAGE_ERROR", "The content transaction could not be completed", {});
  }
}
import type { ContentfnDatabase as Adapter } from "./database.js";
import { enqueueWebhookDelivery } from "./webhookQueue.js";
import { nowISO } from "../time/clock.js";
import { CONTENTFN_TABLE_NAMES } from "./schema.js";

export interface EventsStorageConfig {
  db: Adapter;
  actor?: { subject: string };
}

export interface ContentfnEvent {
  eventId: string;
  dataset: string;
  type: string;
  timestamp: string;
  actor?: { subject: string };
  docId?: string;
  rev?: string;
  changedPaths?: string[];
}

function generateEventId(): string {
  return `evt_${Date.now()}_${Math.random().toString(36).substring(2, 12)}`;
}

export async function appendEvent(
  config: EventsStorageConfig,
  input: {
    dataset: string;
    type: string;
    actor?: { subject: string };
    docId?: string;
    rev?: string;
    changedPaths?: string[];
  }
): Promise<ContentfnEvent> {
  const actor = input.actor ?? config.actor;
  const eventId = generateEventId();
  const timestamp = nowISO();

  const event: ContentfnEvent = {
    eventId,
    dataset: input.dataset,
    type: input.type,
    timestamp,
    actor,
    docId: input.docId,
    rev: input.rev,
    changedPaths: input.changedPaths || [],
  };

  await config.db.create({
    model: CONTENTFN_TABLE_NAMES.events,
    data: {
      id: eventId,
      eventId,
      dataset: input.dataset,
      type: input.type,
      timestamp,
      actor: actor || null,
      docId: input.docId || null,
      rev: input.rev || null,
      changedPaths: input.changedPaths || [],
    },
  });

  const hooks = await config.db.findMany({ model: CONTENTFN_TABLE_NAMES.webhooks, where: [{ field: "dataset", operator: "eq", value: input.dataset }] });
  for (const hook of hooks) {
    if (Array.isArray(hook.events) && hook.events.includes(input.type)) {
      await enqueueWebhookDelivery(config, { eventId, webhookId: hook.webhookId as string });
    }
  }
  return event;
}
