    await config.db.deleteMany({ model: table, where: [{ field: "dataset", operator: "eq", value: name }] });
  }
  await config.db.deleteMany({ model: CONTENTFN_TABLE_NAMES.datasets, where: [{ field: "name", operator: "eq", value: name }] });
  return ok({});
}
