  try {
    if (!config.allowedDatasets.includes(dataset) || !await authorize(config, req, { dataset, type: "*", action: "audit.read" })) return err("PERMISSION_DENIED", "Permission denied");
  } catch { return err("PERMISSION_DENIED", "Permission denied"); }
