    datasets: [{ name: "prod" }],
    desk: { kind: "divider" },
    auth: { kind: "custom" },
    getRolesForSubject: async (): Promise<CmsfnRole[]> => [
      { id: "auditor", name: "Auditor", rules: [{ datasets: "*", types: "*", actions: ["audit.read"] }] },
