    dataset: string;
    filename: string;
    contentType: string;
    bytesBase64: string;
  }
): Promise<ContentfnEnvelope<{ assetId: string; url: string }>> {
  const base = normalizeBaseUrl(config.baseUrl);
  return postJson<{ assetId: string; url: string }>(base, "/contentfn/assets/upload", input);
}

