}

export function PublishButton({
  cmsfnApiUrl,
  dataset,
  docId,
  isPublished = false,
  onPublished,
  onUnpublished,
  disabled,
}: PublishButtonProps) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handlePublish = async () => {
    setError(null);
    setLoading(true);
    const res = await publishDoc({ apiUrl: cmsfnApiUrl }, dataset, docId);
