    if (res.ok) {
      onPublished?.();
    } else {
      setError(res.error.message);
    }
  };

  const handleUnpublish = async () => {
    setError(null);
    setLoading(true);
    const res = await unpublishDoc({ apiUrl: cmsfnApiUrl }, dataset, docId);
    setLoading(false);
    if (res.ok) {
      onUnpublished?.();
    } else {
      setError(res.error.message);
    }
  };

  return (
    <div data-publish-controls>
      {error && <p data-publish-error role="alert">{error}</p>}
      {!isPublished ? (
        <button
