# PHASE_04: Document lists (CFQL-powered panes)

## Phase goal

Implement document list panes that query ContentFn via CFQL deterministically, including pagination and error surfacing.

## In scope

- Studio list pane UI for desk nodes of kind `documentList`.
- ContentFn client integration (HTTP) for CFQL queries.
- Deterministic ordering behavior (explicit orderBy or ContentFn default).
- Cursor pagination handling as opaque values.
- Deterministic error state when ContentFn query fails.

## Out of scope

- Document editor (PHASE_05)
- Reference expansion and picker (PHASE_09)

## Deliverables

- `cmsfn/studio/src/panes/list/DocumentListPane.tsx`
- `cmsfn/studio/src/contentfn/client.ts` (typed client wrapper)
- `cmsfn/studio/src/panes/list/useCfqlQuery.ts`
- `cmsfn/studio/src/panes/list/ListErrorState.tsx`
- Tests implementing:
  - TV-LIST-QUERY-001
  - TV-LIST-PAGINATION-001
  - TV-LIST-QUERY-002

## Requirements covered

- DOC-001
- STUDIO-002 (dataset scoping; continued)

## Implementation tasks

1. Map desk node to a CFQL query:
   - dataset from selector
   - types from desk node
   - orderBy from node defaultOrder (if provided)
2. Implement paging:
   - store `nextCursor` from ContentFn
   - request next page using cursor without parsing/mutation
3. Implement deterministic error surfacing:
   - display error summary + retry action
4. Add tests verifying network calls contain correct dataset/types and cursor opacity.

## Verification steps

- Run list pane tests; confirm repeated loads yield the same ordering for unchanged backend state.

## Stop condition

- List panes are functional, deterministic, and pass referenced TVs.

/**
 * ContentFn Query Language (CFQL) types (SPEC.md).
 */

import type { ContentfnDocument } from "../schema/types.js";

export type CfqlOperator =
  | "eq"
  | "ne"
  | "gt"
  | "gte"
  | "lt"
  | "lte"
  | "in"
  | "not_in"
  | "contains"
  | "starts_with"
  | "ends_with"
  | "is_null"
  | "is_not_null"
  | "match";

export type CfqlFilter =
  | { op: "and"; filters: CfqlFilter[] }
  | { op: "or"; filters: CfqlFilter[] }
  | { field: string; op: CfqlOperator; value?: unknown };

export interface CfqlOrderBy {
  field: string;
  direction: "asc" | "desc";
}

export interface CfqlProjection {
  fields?: string[];
  expand?: Record<
    string,
    {
      field: string;
      projection?: CfqlProjection;
    }
  >;
}

export interface CfqlQuery {
  dataset: string;
  types?: string[];
  filter?: CfqlFilter;
  orderBy?: CfqlOrderBy[];
  projection?: CfqlProjection;
  limit?: number;
  cursor?: string | null;
}

export interface CfqlResultPage {
  data: ContentfnDocument[];
  nextCursor: string | null;
}

export const CFQL_OPERATORS: ReadonlySet<CfqlOperator> = new Set([
  "eq",
  "ne",
  "gt",
  "gte",
  "lt",
  "lte",
  "in",
  "not_in",
  "contains",
  "starts_with",
  "ends_with",
  "is_null",
  "is_not_null",
  "match",
]);
    _id: publishedId,
    _rev: newRev,
    _updatedAt: now,
    _publishedAt: now,
  };

  const existingPublished = await config.db.findOne({
    model: CONTENTFN_TABLE_NAMES.docsPublished,
    where: [
      { field: "dataset", operator: "eq" as const, value: input.dataset },
      { field: "id", operator: "eq" as const, value: documentStorageId(input.dataset, publishedId) },
    ],
  });

  if (existingPublished) {
    await config.db.deleteMany({
      model: CONTENTFN_TABLE_NAMES.docsPublished,
      where: [
        { field: "dataset", operator: "eq" as const, value: input.dataset },
        { field: "id", operator: "eq" as const, value: documentStorageId(input.dataset, publishedId) },
      ],
    });
  }

  await config.db.create({
    model: CONTENTFN_TABLE_NAMES.docsPublished,
    data: {
      dataset: input.dataset,
      id: documentStorageId(input.dataset, publishedId),
      documentId: publishedId,
      type: publishedDoc._type,
      docJson: publishedDoc,
      rev: newRev,
      createdAt: publishedDoc._createdAt,
      updatedAt: now,
      publishedAt: now,
    },
  });

  await appendRevision(
    { db: config.db },
    {
      dataset: input.dataset,
      docId: publishedId,
      perspective: "published",
      rev: newRev,
      docJson: publishedDoc,
    }
  );

  await appendEvent(
    config,
    {
    if (res.ok) {
      setOriginalDoc(res.result);
      setServerError(null);
    } else if (res.error.code === "REV_CONFLICT") {
      setConflict(true);
    } else {
      setServerError({
        code: res.error.code,
        message: res.error.message,
        path: (res.error.details as { path?: string })?.path,
      });
    }
  }, [baseUrl, dataset, docId, schema, docType, formState]);

  if (loading) return <div data-editor-pane data-loading>Loading…</div>;
  if (serverError && !originalDoc) {
    return (
      <div data-editor-pane data-error data-error-code={serverError.code}>
        <p>{serverError.message}</p>
      </div>
    );
  }
  if (typeNotFound) {
    return (
      <div data-editor-pane data-error data-error-code="VALIDATION_FAILED">
        <p>Unknown document type: {(originalDoc as ContentfnDocument)?._type}</p>
      </div>
    );
  }

