  return (
    <div data-publish-controls>
      {error && <p data-publish-error role="alert">{error}</p>}
      {!isPublished ? (
        <button
          type="button"
          data-publish-button
          disabled={disabled || loading}
          onClick={handlePublish}
        >
          {loading ? "Publishing…" : "Publish"}
