    setSaveLoading(true);
    const fullCurrent = { ...formState, _id: docRes.result._id, _type: docRes.result._type };
    const ops = buildPatchOps(docRes.result as Record<string, unknown>, fullCurrent);
    const res = await patchDoc(
      { baseUrl },
