        <button type="button" onClick={() => load(nextCursor)} disabled={loading} data-audit-events-load-more>
          Load more
        </button>
      )}
    </div>
  );
}
/**
 * Webhook deliveries pane: list delivery attempts (webhookId, status, attempt, timestamps), deterministic order.
 */

import { useState, useCallback, useEffect } from "react";
import type { CmsfnWebhookDeliveryStatus } from "cmsfn";

export interface WebhooksPaneProps {
  cmsfnApiUrl: string;
  dataset: string;
  /** When false, show deterministic "no access" state. */
  hasAuditRead?: boolean;
}

function normalizeBaseUrl(url: string): string {
  return url.replace(/\/+$/, "");
}

const DEFAULT_LIMIT = 20;

export function WebhooksPane({ cmsfnApiUrl, dataset, hasAuditRead = true }: WebhooksPaneProps) {
  const [deliveries, setDeliveries] = useState<CmsfnWebhookDeliveryStatus[]>([]);
  const [nextCursor, setNextCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(
    async (cursor?: string | null) => {
      if (!dataset || !hasAuditRead) return;
      setLoading(true);
      setError(null);
      const base = normalizeBaseUrl(cmsfnApiUrl);
      const body: Record<string, unknown> = { dataset, limit: DEFAULT_LIMIT };
      if (cursor != null) body.cursor = cursor;
      const res = await fetch(`${base}/cmsfn/audit/webhooks`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const data = await res.json();
      setLoading(false);
      if (data.ok && data.result) {
        if (cursor) {
          setDeliveries((prev) => [...prev, ...(data.result.deliveries ?? [])]);
        } else {
          setDeliveries(data.result.deliveries ?? []);
        }
        setNextCursor(data.result.nextCursor ?? null);
      } else {
        setError(data?.error?.message ?? "Failed to load deliveries");
        if (!cursor) setDeliveries([]);
      }
    },
    [cmsfnApiUrl, dataset, hasAuditRead]
  );

  useEffect(() => {
    load();
  }, [load]);

  if (!hasAuditRead) {
    return (
      <div data-audit-webhooks-pane data-audit-denied>
        <p data-audit-denied-message>No access</p>
      </div>
    );
  }

  return (
    <div data-audit-webhooks-pane data-dataset={dataset}>
      <h2 data-audit-webhooks-title>Webhook deliveries</h2>
      {error && <p data-audit-webhooks-error>{error}</p>}
      {loading && deliveries.length === 0 && <p data-audit-webhooks-loading>Loading…</p>}
      <ul data-audit-webhooks-list>
        {deliveries.map((d, i) => (
          <li key={`${d.webhookId}-${d.eventId}-${i}`} data-audit-delivery data-webhook-id={d.webhookId}>
            <span data-audit-delivery-status>{d.status}</span>
            <span data-audit-delivery-attempt>{d.attempt}</span>
            <span data-audit-delivery-updated>{d.updatedAt ?? "Timestamp unknown"}</span>
          </li>
        ))}
      </ul>
      {nextCursor && (
        <button type="button" onClick={() => load(nextCursor)} disabled={loading} data-audit-webhooks-load-more>
          Load more
        </button>
      )}
    </div>
  );
}
/**
 * Deterministic desk navigation tree from CmsfnStudioConfig.desk.
 * Uses cmsfn deskNodeKeys for stable keys and order.
 */

import type { CmsfnDeskNode } from "cmsfn";
import { deskNodeKeys } from "cmsfn";

export type DocumentListNode = Extract<CmsfnDeskNode, { kind: "documentList" }>;

export type SingletonNode = Extract<CmsfnDeskNode, { kind: "singleton" }>;

export interface DeskTreeProps {
  root: CmsfnDeskNode;
  onSelectDocumentList?: (node: DocumentListNode) => void;
  onSelectSingleton?: (node: SingletonNode) => void;
}

function DeskNode({ node, nodeKey, onSelectDocumentList, onSelectSingleton }: { node: CmsfnDeskNode; nodeKey: string; onSelectDocumentList?: (node: DocumentListNode) => void; onSelectSingleton?: (node: SingletonNode) => void }) {
  if (node.kind === "divider") {
    return <li key={nodeKey} data-desk-kind="divider" aria-hidden="true" />;
  }
  if (node.kind === "group") {
    return (
      <li key={nodeKey} data-desk-kind="group" data-desk-key={nodeKey}>
        <span data-desk-title>{node.title}</span>
        {node.children.length > 0 && (
          <ul role="group" aria-label={node.title}>
            {node.children.map((child, i) => {
              const key = nodeKey === "0" ? `0-${i}` : `${nodeKey}-${i}`;
              return <DeskNode key={key} node={child} nodeKey={key} onSelectDocumentList={onSelectDocumentList} onSelectSingleton={onSelectSingleton} />;
            })}
          </ul>
        )}
      </li>
    );
  }
  if (node.kind === "documentList") {
    return (
      <li key={nodeKey} data-desk-kind="documentList" data-desk-key={nodeKey} data-desk-dataset={node.dataset}>
        <button type="button" data-desk-list-trigger onClick={() => onSelectDocumentList?.(node)}>
          <span data-desk-title>{node.title}</span>
        </button>
      </li>
    );
  }
  if (node.kind === "singleton") {
    return (
      <li key={nodeKey} data-desk-kind="singleton" data-desk-key={nodeKey} data-desk-dataset={node.dataset} data-desk-type={node.type} data-desk-id={node.id}>
        <button type="button" data-desk-singleton-trigger onClick={() => onSelectSingleton?.(node)}>
          <span data-desk-title>{node.title}</span>
        </button>
      </li>
    );
  }
  return null;
}

/**
 * Renders the desk tree with deterministic keys (depth-first, config order).
 */
export function DeskTree({ root, onSelectDocumentList, onSelectSingleton }: DeskTreeProps) {
  const entries = deskNodeKeys(root);
  if (entries.length === 0) return null;
  const rootEntry = entries[0];
  if (rootEntry.node.kind === "divider") {
    return <nav data-desk-root aria-label="Desk"><ul /></nav>;
  }
  return (
    <nav data-desk-root aria-label="Desk">
      <ul role="tree">
        <DeskNode node={rootEntry.node} nodeKey={rootEntry.key} onSelectDocumentList={onSelectDocumentList} onSelectSingleton={onSelectSingleton} />
      </ul>
    </nav>
  );
}
