/**
 * Studio app shell: desk + dataset selector + list pane.
 * Renders at /studio; config loaded via loadConfig() or passed in for tests.
 */

import { useState, useMemo, useEffect, useCallback } from "react";
import type { CmsfnStudioConfig } from "cmsfn";
import { loadConfig, getInitialDataset } from "./config/loadConfig.js";
import { DeskTree } from "./desk/DeskTree.js";
import type { DocumentListNode } from "./desk/DeskTree.js";
import { DatasetSelector } from "./datasets/DatasetSelector.js";
import { DocumentListPane } from "./panes/list/DocumentListPane.js";
import { DocumentEditorPane } from "./panes/editor/DocumentEditorPane.js";
import { subscribeToDataset } from "./realtime/subscribe.js";
import { applyEvents } from "./realtime/applyEvents.js";

export interface AppProps {
  /** When provided, used instead of loadConfig() (e.g. for tests). */
  config?: CmsfnStudioConfig | null;
}

/**
 * Root Studio app: deterministic desk and dataset selection.
 * Initial dataset = first in config.
 */
export function App({ config: configProp }: AppProps = {}) {
  const configFromWindow = useMemo(() => loadConfig(), []);
  const config = configProp ?? configFromWindow;

  const [dataset, setDataset] = useState<string>(() =>
    config ? getInitialDataset(config) : ""
  );
  const [selectedList, setSelectedList] = useState<DocumentListNode | null>(null);
  const [perspective, setPerspective] = useState<"draft" | "published">("draft");
  const [expectedType, setExpectedType] = useState<string | undefined>();
  const [navigationError, setNavigationError] = useState<string | null>(null);
  const [selectedDocId, setSelectedDocId] = useState<string | null>(null);
  const [listRefreshTrigger, setListRefreshTrigger] = useState(0);
  const [remoteChanged, setRemoteChanged] = useState(false);

  const handleRealtimeEvent = useCallback(
    (event: { type: string; dataset?: string; docId?: string }) => {
      const result = applyEvents(event, {
        openDocId: selectedDocId,
        listDataset: selectedList ? dataset : null,
      });
      if (result.listShouldRefetch) setListRefreshTrigger((t) => t + 1);
      if (result.showRemoteChangedBanner) setRemoteChanged(true);
    },
    [selectedDocId, selectedList, dataset]
  );

  useEffect(() => {
    if (!config?.contentfn?.realtimeUrl || !dataset) return;
    return subscribeToDataset({
      realtimeUrl: config.contentfn.realtimeUrl,
      dataset,
      onEvent: handleRealtimeEvent,
    });
  }, [config?.contentfn?.realtimeUrl, dataset, handleRealtimeEvent]);

  if (!config) {
    return (
      <div data-studio-root data-studio-state="no-config">
        <p>No Studio config available.</p>
      </div>
    );
  }

  return (
    <div data-studio-root data-studio-state="ready" data-current-dataset={dataset}>
      <header data-studio-header>
        <DatasetSelector
          config={config}
          value={dataset}
          onDatasetChange={(next) => { setDataset(next); setSelectedDocId(null); setExpectedType(undefined); setNavigationError(null); setRemoteChanged(false); }}
        />
        <label>Document perspective
          <select aria-label="Document perspective" value={perspective} onChange={(event) => {
            setPerspective(event.target.value === "published" ? "published" : "draft");
            setSelectedDocId(null); setNavigationError(null); setRemoteChanged(false);
          }}>
            <option value="draft">Drafts</option><option value="published">Published</option>
          </select>
        </label>
      </header>
      <aside data-studio-desk>
        <DeskTree
          root={config.desk}
          onSelectDocumentList={(list) => { setSelectedList(list); setSelectedDocId(null); setExpectedType(undefined); setNavigationError(null); setRemoteChanged(false); }}
          onSelectSingleton={(node) => {
            setSelectedList(null); setSelectedDocId(null); setRemoteChanged(false);
            if (!node.id.replace(/^drafts\./, "") || !node.type || !config.datasets.some(item => item.name === node.dataset)) {
              setNavigationError("This singleton is not available in the configured datasets");
              return;
            }
            setNavigationError(null); setDataset(node.dataset); setExpectedType(node.type);
            setSelectedDocId(node.id.replace(/^drafts\./, ""));
          }}
        />
      </aside>
      <main data-studio-pane>
        {navigationError && <p role="alert" data-desk-error>{navigationError}</p>}
        {selectedDocId ? (
          <>
            <button type="button" data-editor-back onClick={() => setSelectedDocId(null)}>
              {selectedList ? "Back to list" : "Back to desk"}
            </button>
            <DocumentEditorPane
              key={`${dataset}:${perspective}:${selectedDocId}`}
              perspective={perspective}
              expectedType={expectedType}
              onOpenDraft={(id) => { setPerspective("draft"); setSelectedDocId(id); }}
              onUnpublished={() => { setSelectedDocId(null); setListRefreshTrigger((value) => value + 1); }}
              baseUrl={config.contentfn.baseUrl}
              dataset={dataset}
              docId={selectedDocId}
              cmsfnApiUrl={config.cmsfn?.apiUrl}
              previewConfig={config.preview}
              realtimeUrl={config.contentfn.realtimeUrl}
              maxUploadBytes={config.limits?.maxUploadBytes}
              remoteChanged={remoteChanged}
              onClearRemoteChanged={() => setRemoteChanged(false)}
            />
          </>
        ) : selectedList ? (
          <DocumentListPane
            key={`${dataset}:${perspective}`}
            perspective={perspective}
            baseUrl={config.contentfn.baseUrl}
            dataset={dataset}
            node={selectedList}
            onOpenDoc={(id) => {
              setSelectedDocId(id);
              setRemoteChanged(false);
            }}
            refreshTrigger={listRefreshTrigger}
          />
        ) : null}
      </main>
    </div>
  );
}
/** Authorized, bounded audit routes. Browser credentials are never forwarded implicitly. */
import type { IncomingMessage } from "http";
import { err, type CmsfnEnvelope } from "cmsfn";
import { authorize, type AuthorizeConfig } from "../auth/authorize.js";
import { contentfnAuditEvents, AUDIT_MAX_LIMIT } from "../audit/events.js";
import { contentfnAuditWebhooks } from "../audit/webhooks.js";
import { readJsonObject } from "./jsonBody.js";

export interface AuditHandlerConfig extends AuthorizeConfig {
  contentfnBaseUrl: string;
  allowedDatasets: string[];
  authorizeAudit?: (req: IncomingMessage) => Promise<boolean>;
  /** Server-owned upstream identity/credentials; receives the authorized request. */
  contentfnAuditHeaders?: (req: IncomingMessage) => NonNullable<RequestInit["headers"]> | Promise<NonNullable<RequestInit["headers"]>>;
}
export const AUDIT_BODY_MAX_BYTES = 64 * 1024;
type AuditInput = { dataset: string; limit?: number; cursor?: string | null };

async function readAuthorizedInput(config: AuditHandlerConfig, req: IncomingMessage): Promise<CmsfnEnvelope<AuditInput>> {
  try {
    if (!config.getRolesForSubject || (config.authorizeAudit && await config.authorizeAudit(req) !== true)) return err("PERMISSION_DENIED", "Permission denied");
  } catch { return err("PERMISSION_DENIED", "Permission denied"); }
  const parsed = await readJsonObject(req, AUDIT_BODY_MAX_BYTES);
  if (!parsed.ok) return parsed;
  const body = parsed.result;
  const dataset = typeof body.dataset === "string" ? body.dataset.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  try {
    if (!config.allowedDatasets.includes(dataset) || !await authorize(config, req, { dataset, type: "*", action: "audit.read" })) return err("PERMISSION_DENIED", "Permission denied");
  } catch { return err("PERMISSION_DENIED", "Permission denied"); }
  if (body.limit !== undefined && (typeof body.limit !== "number" || !Number.isSafeInteger(body.limit) || body.limit < 1 || body.limit > AUDIT_MAX_LIMIT)) return err("VALIDATION_FAILED", "Invalid audit limit", { path: "limit" });
  if (body.cursor !== undefined && body.cursor !== null && (typeof body.cursor !== "string" || body.cursor.length > 2048)) return err("VALIDATION_FAILED", "Invalid audit cursor", { path: "cursor" });
  return { ok: true, result: { dataset, ...(body.limit === undefined ? {} : { limit: body.limit as number }), ...(body.cursor === undefined ? {} : { cursor: body.cursor as string | null }) } };
}

export async function handleAuditEvents(config: AuditHandlerConfig, req: IncomingMessage): Promise<CmsfnEnvelope<{ events: import("cmsfn").CmsfnAuditEvent[]; nextCursor: string | null }>> {
  const input = await readAuthorizedInput(config, req);
  if (!input.ok) return input;
  try {
    const headers = await config.contentfnAuditHeaders?.(req);
    return await contentfnAuditEvents({ contentfnBaseUrl: config.contentfnBaseUrl, headers }, input.result);
  } catch { return err("CONTENTFN_UNAVAILABLE", "ContentFn audit request could not be configured"); }
}

/** Authorized dataset-wide delivery metadata from ContentFn schema4. */
export async function handleAuditWebhooks(config: AuditHandlerConfig, req: IncomingMessage): Promise<CmsfnEnvelope<{ deliveries: import("cmsfn").CmsfnWebhookDeliveryStatus[]; nextCursor: string | null }>> {
  const input = await readAuthorizedInput(config, req);
  if (!input.ok) return input;
  try {
    const headers = await config.contentfnAuditHeaders?.(req);
    return await contentfnAuditWebhooks({ contentfnBaseUrl: config.contentfnBaseUrl, headers }, input.result);
  } catch { return err("CONTENTFN_UNAVAILABLE", "ContentFn audit request could not be configured"); }
}
