/**
 * Minimal releases pane: list releases, create release, publish release.
 */

import { useState, useCallback, useEffect } from "react";
import type { CmsfnRelease, CmsfnReleasePublishResult } from "cmsfn";

export interface ReleasesPaneProps {
  cmsfnApiUrl: string;
  dataset: string;
}

function normalizeBaseUrl(url: string): string {
  return url.replace(/\/+$/, "");
}

export function ReleasesPane({ cmsfnApiUrl, dataset }: ReleasesPaneProps) {
  const [releases, setReleases] = useState<CmsfnRelease[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [createName, setCreateName] = useState("");
  const [publishResult, setPublishResult] = useState<CmsfnReleasePublishResult | null>(null);

  const loadReleases = useCallback(async () => {
    if (!dataset) return;
    setLoading(true);
    setError(null);
    const base = normalizeBaseUrl(cmsfnApiUrl);
    const res = await fetch(`${base}/cmsfn/releases/list`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dataset }),
    });
    const data = await res.json();
    setLoading(false);
    if (data.ok && data.result?.releases) {
      setReleases(data.result.releases);
    } else {
      setError(data?.error?.message ?? "Failed to list releases");
    }
  }, [cmsfnApiUrl, dataset]);

  useEffect(() => {
    loadReleases();
  }, [loadReleases]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!createName.trim() || !dataset) return;
    setError(null);
    const base = normalizeBaseUrl(cmsfnApiUrl);
    const res = await fetch(`${base}/cmsfn/releases/create`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dataset, name: createName.trim(), publishAt: null }),
    });
    const data = await res.json();
    if (data.ok) {
      setCreateName("");
      await loadReleases();
    } else {
      setError(data?.error?.message ?? "Failed to create release");
    }
  };

  const handlePublish = async (releaseId: string) => {
    setError(null);
    setPublishResult(null);
    const base = normalizeBaseUrl(cmsfnApiUrl);
    const res = await fetch(`${base}/cmsfn/releases/publish`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dataset, releaseId }),
    });
    const data = await res.json();
    if (data.ok && data.result) {
      setPublishResult(data.result);
      await loadReleases();
    } else {
      setError(data?.error?.message ?? "Failed to publish release");
    }
  };

  return (
    <div data-releases-pane data-dataset={dataset}>
      <h2 data-releases-title>Releases</h2>
      <form onSubmit={handleCreate} data-releases-create-form>
        <input
          type="text"
          placeholder="Release name"
          value={createName}
          onChange={(e) => setCreateName(e.target.value)}
          data-releases-create-name
        />
        <button type="submit" data-releases-create-submit>
          Create release
        </button>
      </form>
      {error && <p data-releases-error>{error}</p>}
      {publishResult && (
        <div data-releases-publish-result>
          <p>Published: {publishResult.published.length}</p>
          {publishResult.failures.length > 0 && (
            <p data-releases-failures>Failures: {publishResult.failures.length}</p>
          )}
        </div>
      )}
      {loading && <p data-releases-loading>Loading…</p>}
      <ul data-releases-list>
        {releases.map((r) => (
          <li key={r.releaseId} data-releases-item data-release-id={r.releaseId}>
            <span data-releases-item-name>{r.name}</span>
            <span data-releases-item-doc-count>{r.docIds.length} docs</span>
            <button
              type="button"
              onClick={() => handlePublish(r.releaseId)}
              data-releases-publish
              data-release-id={r.releaseId}
            >
              Publish
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
/**
 * CmsFn release model types (SPEC.md).
 */

export interface CmsfnRelease {
  releaseId: string;
  dataset: string;
  name: string;
  publishAt?: string | null; // ISO 8601 or null
  docIds: string[];
  createdAt: string; // ISO 8601
  updatedAt: string; // ISO 8601
}

export interface CmsfnReleasePublishResult {
  releaseId: string;
  published: string[]; // doc IDs
  failures: Array<{ docId: string; code: string; message: string }>;
}
# PHASE_10: Releases (batch publish + scheduling)

## Phase goal

Implement releases as named batches of draft documents with deterministic publish behavior, including optional scheduling.

## In scope

- Server endpoints:
  - `POST /cmsfn/releases/create`
  - `POST /cmsfn/releases/list`
  - `POST /cmsfn/releases/add`
  - `POST /cmsfn/releases/publish`
- Release storage model and deterministic ordering
- Publish orchestration calling ContentFn publish per doc:
  - enforce permissions and workflow gates
  - return deterministic summary of successes/failures

## Out of scope

- Complex transactional semantics across multiple docs (documented best-effort is acceptable but must be deterministic)

## Deliverables

- `cmsfn/server/src/http/releases.ts`
- `cmsfn/server/src/storage/releases.ts`
- `cmsfn/server/src/releases/publishRelease.ts`
- Studio UI minimal pane:
  - `cmsfn/studio/src/panes/releases/ReleasesPane.tsx`
- Tests implementing:
  - TV-REL-CREATE-001
  - TV-REL-ADD-001
  - TV-REL-PUBLISH-001
  - TV-REL-PUBLISH-002

## Requirements covered

- REL-001
- WF-001 (publish gating)
- ROLE-001 (release.manage + doc.publish)

## Implementation tasks

1. Implement release CRUD storage and deterministic ordering (createdAt desc, releaseId asc).
2. Implement create/list/add endpoints with validation.
3. Implement publish:
   - evaluate workflow gate per doc
   - publish sequentially in deterministic order (sorted docIds)
   - collect failures deterministically
4. Add tests for successful and failing publish cases.

## Verification steps

- Run release tests.
- Confirm publish result ordering is stable.

## Stop condition

- Releases work end-to-end and publish results are deterministic.

/**
 * CmsFn release storage via @superfunctions/db adapter.
 * Table: cmsfn_releases (releaseId, dataset, name, publishAt, docIds, createdAt, updatedAt).
 * List order: createdAt desc, releaseId asc.
 */

import type { Adapter } from "@superfunctions/db";
import { cmsfnStorageAdapter } from "./schema.js";
import type { CmsfnEnvelope, CmsfnRelease } from "cmsfn";
import { ok, err } from "cmsfn";
import { randomUUID } from "node:crypto";
import { MAX_DOCS_PER_RELEASE } from "../limits/limits.js";

export const CMSFN_RELEASES_TABLE = "cmsfn_releases";

export interface ReleasesStorageConfig {
  db: Adapter;
}

interface ReleaseRow {
  releaseId: string;
  dataset: string;
  name: string;
  publishAt: string | null;
  docIds: string[];
  createdAt: string;
  updatedAt: string;
}

function nowIso(): string {
  return new Date().toISOString();
}

/**
 * Create a release. Returns releaseId.
 */
export async function createRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; name: string; publishAt?: string | null }
): Promise<CmsfnEnvelope<{ releaseId: string }>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const name = typeof input.name === "string" ? input.name.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  if (!name) return err("VALIDATION_FAILED", "name is required", { path: "name" });
  const publishAt =
    input.publishAt === undefined || input.publishAt === null
      ? null
      : typeof input.publishAt === "string"
        ? input.publishAt.trim() || null
        : null;

  const releaseId = randomUUID();
  const now = nowIso();
  const row: ReleaseRow = {
    releaseId,
    dataset,
    name,
    publishAt,
    docIds: [],
    createdAt: now,
    updatedAt: now,
  };
  await cmsfnStorageAdapter(config.db).create({
    model: CMSFN_RELEASES_TABLE,
    data: row,
  });
  return ok({ releaseId });
}

/**
 * List releases for dataset. Order: createdAt desc, releaseId asc.
 */
export async function listReleases(
  config: ReleasesStorageConfig,
  input: { dataset: string }
): Promise<CmsfnEnvelope<{ releases: CmsfnRelease[] }>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });

  const rows = await cmsfnStorageAdapter(config.db).findMany({
    model: CMSFN_RELEASES_TABLE,
    where: [{ field: "dataset", operator: "eq", value: dataset }],
    orderBy: [
      { field: "createdAt", direction: "desc" },
      { field: "releaseId", direction: "asc" },
    ],
  });
  const releases: CmsfnRelease[] = (rows as ReleaseRow[]).map((r) => ({
    releaseId: r.releaseId,
    dataset: r.dataset,
    name: r.name,
    publishAt: r.publishAt,
    docIds: Array.isArray(r.docIds) ? r.docIds : [],
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
  }));
  return ok({ releases });
}

/**
 * Get one release by dataset and releaseId.
 */
export async function getRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; releaseId: string }
): Promise<CmsfnRelease | null> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const releaseId = typeof input.releaseId === "string" ? input.releaseId.trim() : "";
  if (!dataset || !releaseId) return null;

  const row = await cmsfnStorageAdapter(config.db).findOne({
    model: CMSFN_RELEASES_TABLE,
    where: [
      { field: "dataset", operator: "eq", value: dataset },
      { field: "releaseId", operator: "eq", value: releaseId },
    ],
  });
  if (!row || typeof row !== "object") return null;
  const r = row as ReleaseRow;
  return {
    releaseId: r.releaseId,
    dataset: r.dataset,
    name: r.name,
    publishAt: r.publishAt,
    docIds: Array.isArray(r.docIds) ? r.docIds : [],
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
  };
}

/**
 * Add a doc to a release. Rejects if release not found or docIds would exceed max.
 */
export async function addDocToRelease(
  config: ReleasesStorageConfig,
  input: { dataset: string; releaseId: string; docId: string }
): Promise<CmsfnEnvelope<Record<string, never>>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const releaseId = typeof input.releaseId === "string" ? input.releaseId.trim() : "";
  const docId = typeof input.docId === "string" ? input.docId.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  if (!releaseId) return err("VALIDATION_FAILED", "releaseId is required", { path: "releaseId" });
  if (!docId) return err("VALIDATION_FAILED", "docId is required", { path: "docId" });

  const release = await getRelease(config, { dataset, releaseId });
  if (!release) return err("NOT_FOUND", "Release not found", { releaseId });

  const docIds = [...release.docIds];
  if (docIds.includes(docId)) return ok({});
  if (docIds.length >= MAX_DOCS_PER_RELEASE) {
    return err("VALIDATION_FAILED", "Release has reached max document count", {
      path: "docId",
      limit: MAX_DOCS_PER_RELEASE,
    });
  }
  docIds.push(docId);
  docIds.sort();

  await cmsfnStorageAdapter(config.db).update({
    model: CMSFN_RELEASES_TABLE,
    where: [
      { field: "dataset", operator: "eq", value: dataset },
      { field: "releaseId", operator: "eq", value: releaseId },
    ],
    data: { docIds, updatedAt: nowIso() },
  });
  return ok({});
}

