    const after = await getRelease({ db }, input);
    expect(after?.docIds).toEqual(['a', 'b']);
    expect(Date.parse(after!.updatedAt)).toBeGreaterThan(Date.parse(before!.updatedAt));
  } finally { await db.close(); }
});
