/**
 * Minimal ops pane: trigger export and import for a dataset.
 */

import { useState, useCallback } from "react";

export interface OpsPaneProps {
  cmsfnApiUrl: string;
  dataset: string;
}

function normalizeBaseUrl(url: string): string {
  return url.replace(/\/+$/, "");
}

export function OpsPane({ cmsfnApiUrl, dataset }: OpsPaneProps) {
  const [exportLoading, setExportLoading] = useState(false);
  const [exportResult, setExportResult] = useState<unknown>(null);
  const [exportError, setExportError] = useState<string | null>(null);
  const [importLoading, setImportLoading] = useState(false);
  const [importArtifact, setImportArtifact] = useState("");
  const [importError, setImportError] = useState<string | null>(null);

  const handleExport = useCallback(async () => {
    if (!dataset) return;
    setExportLoading(true);
    setExportError(null);
    setExportResult(null);
    const base = normalizeBaseUrl(cmsfnApiUrl);
    const res = await fetch(`${base}/cmsfn/ops/export`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dataset }),
    });
    const data = await res.json();
    setExportLoading(false);
    if (data.ok && data.result?.artifact) {
      setExportResult(data.result.artifact);
    } else {
      setExportError(data?.error?.message ?? "Export failed");
    }
  }, [cmsfnApiUrl, dataset]);

  const handleImport = useCallback(async () => {
    if (!dataset || !importArtifact.trim()) return;
    let artifact: unknown;
    try {
      artifact = JSON.parse(importArtifact);
    } catch {
      setImportError("Invalid JSON");
      return;
    }
    setImportLoading(true);
    setImportError(null);
    const base = normalizeBaseUrl(cmsfnApiUrl);
    const res = await fetch(`${base}/cmsfn/ops/import`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dataset, artifact }),
    });
    const data = await res.json();
    setImportLoading(false);
    if (!data.ok) {
      setImportError(data?.error?.message ?? "Import failed");
    }
  }, [cmsfnApiUrl, dataset, importArtifact]);

  return (
    <div data-ops-pane data-dataset={dataset}>
      <h2 data-ops-title>Ops</h2>
      <section data-ops-export>
        <h3>Export</h3>
        <button type="button" onClick={handleExport} disabled={exportLoading || !dataset} data-ops-export-trigger>
          {exportLoading ? "Exporting…" : "Export dataset"}
        </button>
        {exportError && <p data-ops-export-error>{exportError}</p>}
        {exportResult != null && <pre data-ops-export-result>{JSON.stringify(exportResult, null, 2).slice(0, 500)}…</pre>}
      </section>
      <section data-ops-import>
        <h3>Import</h3>
        <textarea
          placeholder="Paste artifact JSON"
          value={importArtifact}
          onChange={(e) => setImportArtifact(e.target.value)}
          data-ops-import-artifact
          rows={6}
        />
        <button type="button" onClick={handleImport} disabled={importLoading || !importArtifact.trim()} data-ops-import-trigger>
          {importLoading ? "Importing…" : "Import to dataset"}
        </button>
        {importError && <p data-ops-import-error>{importError}</p>}
      </section>
    </div>
  );
}
# PHASE_11: Ops import/export triggers

## Phase goal

Implement operational endpoints to trigger ContentFn dataset export/import with strict dataset isolation and deterministic responses.

## In scope

- Server endpoints:
  - `POST /cmsfn/ops/export`
  - `POST /cmsfn/ops/import`
- Permission enforcement:
  - require `audit.read` and/or a dedicated ops permission (documented; deterministic)
- Dataset isolation checks
- Studio UI triggers (minimal)

## Out of scope

- Background job queue UI (unless required by deployment scale; otherwise synchronous is acceptable)

## Deliverables

- `cmsfn/server/src/http/ops.ts`
- `cmsfn/server/src/ops/export.ts`
- `cmsfn/server/src/ops/import.ts`
- `cmsfn/studio/src/panes/ops/OpsPane.tsx`
- Tests implementing:
  - TV-OPS-EXPORT-001
  - TV-OPS-IMPORT-001
  - TV-OPS-IMPORT-002

## Requirements covered

- OPS-001

## Implementation tasks

1. Implement export:
   - call ContentFn dataset export for requested dataset
   - return artifact in envelope (or deterministic job handle if async)
2. Implement import:
   - validate artifact shape
   - call ContentFn dataset import for target dataset
3. Enforce dataset isolation (no import writes outside target dataset).
4. Add tests for success and malformed artifacts.

## Verification steps

- Run ops tests.

## Stop condition

- Ops endpoints behave deterministically and preserve dataset isolation.

