/**
 * Publish a release: for each doc (sorted), check permission + workflow gate, call ContentFn publish.
 * Returns deterministic summary: published[], failures[].
 */

import type { IncomingMessage } from "http";
import { ok } from "cmsfn";
import { CMS_RESERVED_FIELD } from "cmsfn";
import type { CmsfnWorkflowMetadata, CmsfnReleasePublishResult, CmsfnEnvelope } from "cmsfn";
import { authorize } from "../auth/authorize.js";
import type { AuthorizeConfig } from "../auth/authorize.js";
import { canPublish } from "../publish/gates.js";
import { getDraftDoc, contentfnPublish } from "../publish/contentfnClient.js";
import { getRelease } from "../storage/releases.js";
import type { ReleasesStorageConfig } from "../storage/releases.js";

export interface PublishReleaseConfig extends AuthorizeConfig {
  contentfnBaseUrl: string;
  releasesStorage: ReleasesStorageConfig;
}

function getWorkflowState(doc: Record<string, unknown>): string | undefined {
  const cms = doc[CMS_RESERVED_FIELD] as CmsfnWorkflowMetadata | undefined;
  return cms?.state;
}

/**
 * Publish all docs in a release. Doc order: sorted docIds (deterministic).
 * For each doc: check doc.publish for doc's _type, workflow gate, then ContentFn publish.
 * Returns { releaseId, published, failures }.
 */
export async function publishRelease(
  config: PublishReleaseConfig,
  req: IncomingMessage,
  input: { dataset: string; releaseId: string }
): Promise<CmsfnEnvelope<CmsfnReleasePublishResult>> {
  const dataset = typeof input.dataset === "string" ? input.dataset.trim() : "";
  const releaseId = typeof input.releaseId === "string" ? input.releaseId.trim() : "";
  if (!dataset) return { ok: false, error: { code: "VALIDATION_FAILED", message: "dataset is required", details: { path: "dataset" } } };
  if (!releaseId) return { ok: false, error: { code: "VALIDATION_FAILED", message: "releaseId is required", details: { path: "releaseId" } } };

  const release = await getRelease(config.releasesStorage, { dataset, releaseId });
  if (!release) return { ok: false, error: { code: "NOT_FOUND", message: "Release not found", details: { releaseId } } };

  const docIds = [...release.docIds].sort();
  const published: string[] = [];
  const failures: Array<{ docId: string; code: string; message: string }> = [];

  const contentfn = { baseUrl: config.contentfnBaseUrl };

  for (const docId of docIds) {
    const draftRes = await getDraftDoc(contentfn, dataset, docId);
    if (!draftRes.ok) {
      failures.push({
        docId,
        code: draftRes.error.code,
        message: draftRes.error.message,
      });
      continue;
    }
    const draftDoc = draftRes.result as Record<string, unknown>;
    const docType = (draftDoc._type as string) ?? "*";
    const state = getWorkflowState(draftDoc);

    const hasDocPublish = await authorize(config, req, {
      dataset,
      type: docType,
      action: "doc.publish",
    });
    if (!hasDocPublish) {
      failures.push({ docId, code: "PERMISSION_DENIED", message: "Permission denied" });
      continue;
    }
    if (!canPublish(state as "draft" | "in_review" | "approved" | "published", true)) {
      failures.push({
        docId,
        code: "PERMISSION_DENIED",
        message: "Workflow state does not allow publish",
      });
      continue;
    }

    const pubRes = await contentfnPublish(contentfn, dataset, docId, draftRes.result._rev);
    if (pubRes.ok) {
      published.push(docId);
    } else {
      failures.push({
        docId,
        code: pubRes.error.code,
        message: pubRes.error.message,
      });
    }
  }

  return ok({
    releaseId,
    published,
    failures,
  });
}
import type { Adapter, TableSchemaMap } from "@superfunctions/db";
import { wrapWithSchema } from "@superfunctions/db/schema";

/**
 * CmsFn owns serialization; applications supply adapters without adapterSchema.
 * SQL tables use TEXT for rules/docIds; timestamps remain ISO strings.
 * This descriptor does not create tables or migrate existing native JSON columns.
 */
export function getCmsfnStorageSchema(): TableSchemaMap {
  return {
    cmsfn_roles: {
      modelName: "cmsfn_roles",
      fields: {
        id: { type: "string", required: true, unique: true },
        name: { type: "string", required: true },
        rules: { type: "json", jsonStorageType: "json-text", required: true },
      },
    },
    cmsfn_releases: {
      modelName: "cmsfn_releases",
      fields: {
        releaseId: { type: "string", required: true, unique: true },
        dataset: { type: "string", required: true },
        name: { type: "string", required: true },
        publishAt: { type: "string" },
        docIds: { type: "json", jsonStorageType: "json-text", required: true },
        createdAt: { type: "string", required: true },
        updatedAt: { type: "string", required: true },
      },
      indexes: [{ name: "cmsfn_releases_dataset", fields: ["dataset"] }],
    },
  };
}

const adapters = new WeakMap<Adapter, Adapter>();

/** Retains the supplied adapter's table mapping, namespace and lifecycle. */
export function cmsfnStorageAdapter(adapter: Adapter): Adapter {
  let wrapped = adapters.get(adapter);
  if (!wrapped) {
    const schema = getCmsfnStorageSchema();
    // Memory already holds native arrays, including rows written before CmsFn
    // owned its schema. SQL persistence uses explicit TEXT JSON columns.
    if (adapter.id === "memory") {
      schema.cmsfn_roles.fields.rules.jsonStorageType = "native";
      schema.cmsfn_releases.fields.docIds.jsonStorageType = "native";
    }
    wrapped = wrapWithSchema(adapter, schema);
    adapters.set(adapter, wrapped);
  }
  return wrapped;
}
/**
 * POST /cmsfn/releases/create, list, add, publish.
 * create/list/add require release.manage; publish requires release.manage and per-doc doc.publish + workflow.
 */

import type { IncomingMessage } from "http";
import { err, type CmsfnEnvelope } from "cmsfn";
import { readJsonObject } from "./jsonBody.js";
import { createRelease, listReleases, addDocToRelease } from "../storage/releases.js";
import type { ReleasesStorageConfig } from "../storage/releases.js";
import { publishRelease } from "../releases/publishRelease.js";
import { authorize } from "../auth/authorize.js";
import type { AuthorizeConfig } from "../auth/authorize.js";

import type { CapabilityGateConfig } from "../contentfn/statusClient.js";
export interface ReleasesHandlerConfig extends AuthorizeConfig, CapabilityGateConfig {
  releasesStorage: ReleasesStorageConfig;
  contentfnBaseUrl: string;
  /** Server-configured dataset names; role grants cannot enable another dataset. */
  allowedDatasets?: readonly string[];
  /** Optional: if provided and returns false, respond PERMISSION_DENIED for create/list/add/publish. */
  authorizeReleases?: (req: IncomingMessage) => Promise<boolean>;
}

export const RELEASE_BODY_MAX_BYTES = 64 * 1024;

async function readAuthorizedBody(
  config: ReleasesHandlerConfig,
  req: IncomingMessage
): Promise<CmsfnEnvelope<Record<string, unknown>>> {
  // Missing identity configuration and an explicit outer veto need no body read.
  try {
    if (!config.getRolesForSubject || (config.authorizeReleases && await config.authorizeReleases(req) !== true)) {
      return err("PERMISSION_DENIED", "Permission denied");
    }
  } catch {
    return err("PERMISSION_DENIED", "Permission denied");
  }
  const parsed = await readJsonObject(req, RELEASE_BODY_MAX_BYTES);
  if (!parsed.ok) return parsed;
  const dataset = typeof parsed.result.dataset === "string" ? parsed.result.dataset.trim() : "";
  if (!dataset) return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  try {
    if ((config.allowedDatasets && !config.allowedDatasets.includes(dataset)) ||
      !await authorize(config, req, { dataset, type: "*", action: "release.manage" })) {
      return err("PERMISSION_DENIED", "Permission denied");
    }
  } catch {
    return err("PERMISSION_DENIED", "Permission denied");
  }
  return parsed;
}

/**
 * POST /cmsfn/releases/create — body: { dataset, name, publishAt? }.
 */
export async function handleReleasesCreate(
  config: ReleasesHandlerConfig,
  req: IncomingMessage
): Promise<CmsfnEnvelope<{ releaseId: string }>> {
  const parsed = await readAuthorizedBody(config, req);
  if (!parsed.ok) return parsed;
  const body = parsed.result;
  const dataset = typeof body?.dataset === "string" ? body.dataset.trim() : "";
  const name = typeof body?.name === "string" ? body.name.trim() : "";
  const publishAt = body?.publishAt;
  if (!dataset) {
    return { ok: false, error: { code: "VALIDATION_FAILED", message: "dataset is required", details: { path: "dataset" } } };
  }
  if (!name) {
    return { ok: false, error: { code: "VALIDATION_FAILED", message: "name is required", details: { path: "name" } } };
  }
  return createRelease(config.releasesStorage, {
    dataset,
    name,
    publishAt: publishAt === undefined || publishAt === null ? null : (publishAt as string),
  });
}

/**
 * POST /cmsfn/releases/list — body: { dataset }.
 */
export async function handleReleasesList(
  config: ReleasesHandlerConfig,
  req: IncomingMessage
): Promise<CmsfnEnvelope<{ releases: import("cmsfn").CmsfnRelease[] }>> {
  const parsed = await readAuthorizedBody(config, req);
  if (!parsed.ok) return parsed;
  const body = parsed.result;
  const dataset = typeof body?.dataset === "string" ? body.dataset.trim() : "";
  if (!dataset) {
    return { ok: false, error: { code: "VALIDATION_FAILED", message: "dataset is required", details: { path: "dataset" } } };
  }
  return listReleases(config.releasesStorage, { dataset });
}

/**
 * POST /cmsfn/releases/add — body: { dataset, releaseId, docId }.
 */
export async function handleReleasesAdd(
  config: ReleasesHandlerConfig,
  req: IncomingMessage
): Promise<CmsfnEnvelope<Record<string, never>>> {
  const parsed = await readAuthorizedBody(config, req);
  if (!parsed.ok) return parsed;
  const body = parsed.result;
  const dataset = typeof body?.dataset === "string" ? body.dataset.trim() : "";
  const releaseId = typeof body?.releaseId === "string" ? body.releaseId.trim() : "";
  const docId = typeof body?.docId === "string" ? body.docId.trim() : "";
  if (!dataset) {
    return { ok: false, error: { code: "VALIDATION_FAILED", message: "dataset is required", details: { path: "dataset" } } };
  }
  if (!releaseId) {
    return { ok: false, error: { code: "VALIDATION_FAILED", message: "releaseId is required", details: { path: "releaseId" } } };
  }
  if (!docId) {
    return { ok: false, error: { code: "VALIDATION_FAILED", message: "docId is required", details: { path: "docId" } } };
  }
  return addDocToRelease(config.releasesStorage, { dataset, releaseId, docId });
}

/**
 * POST /cmsfn/releases/publish — body: { dataset, releaseId }.
 */
export async function handleReleasesPublish(
  config: ReleasesHandlerConfig,
  req: IncomingMessage
): Promise<CmsfnEnvelope<import("cmsfn").CmsfnReleasePublishResult>> {
  const parsed = await readAuthorizedBody(config, req);
  if (!parsed.ok) return parsed;
  const body = parsed.result;
  const dataset = typeof body?.dataset === "string" ? body.dataset.trim() : "";
  const releaseId = typeof body?.releaseId === "string" ? body.releaseId.trim() : "";
  if (!dataset) {
    return { ok: false, error: { code: "VALIDATION_FAILED", message: "dataset is required", details: { path: "dataset" } } };
  }
  if (!releaseId) {
    return { ok: false, error: { code: "VALIDATION_FAILED", message: "releaseId is required", details: { path: "releaseId" } } };
  }
  if (config.checkCapabilities && !await config.checkCapabilities(req, ["content.docs"])) return err("CONTENTFN_UNAVAILABLE", "ContentFn document capability is unavailable");
  return publishRelease(
    {
      getRolesForSubject: async (request) => {
        try { return await config.getRolesForSubject!(request); } catch { return []; }
      },
      contentfnBaseUrl: config.contentfnBaseUrl,
      releasesStorage: config.releasesStorage,
    },
    req,
    { dataset, releaseId }
  );
}
