/**
 * POST /cmsfn/preview/token — mint short-lived preview token (dataset + docIds bound).
 */

import type { IncomingMessage } from "http";
import type { CmsfnEnvelope, CmsfnPreviewTokenResult } from "cmsfn";
import { ok, err } from "cmsfn";
import { authorize } from "../auth/authorize.js";
import type { AuthorizeConfig } from "../auth/authorize.js";
import { mintPreviewToken } from "../preview/tokens.js";

import type { CapabilityGateConfig } from "../contentfn/statusClient.js";
import { readJsonObject } from "./jsonBody.js";
export interface PreviewTokenHandlerConfig extends AuthorizeConfig, CapabilityGateConfig {
  allowedDatasets?: readonly string[];
  /** When false or unset, return PREVIEW_NOT_CONFIGURED. */
  previewEnabled?: boolean;
  /** Secret for signing tokens; required when preview enabled. */
  previewSecret?: string;
  ttlSec?: number;
}

/**
 * Handle POST /cmsfn/preview/token.
 * Body: { dataset: string; docId?: string; docIds?: string[] }.
 * Accepts docId (single) or docIds (array); normalizes to docIds.
 */
export async function handlePreviewToken(
  config: PreviewTokenHandlerConfig,
  req: IncomingMessage
): Promise<CmsfnEnvelope<CmsfnPreviewTokenResult>> {
  if (!config.previewEnabled || !config.previewSecret) {
    return err("PREVIEW_NOT_CONFIGURED", "Preview is not configured", {});
  }

  const parsed = await readJsonObject(req, 64 * 1024); if (!parsed.ok) return parsed;
  const body = parsed.result;
  const dataset = body?.dataset;
  if (typeof dataset !== "string" || dataset.trim().length === 0) {
    return err("VALIDATION_FAILED", "dataset is required", { path: "dataset" });
  }
  const ds = dataset.trim();

  let docIds: string[];
  if (Array.isArray(body?.docIds) && body.docIds.every((id: unknown) => typeof id === "string")) {
    docIds = (body.docIds as string[]).map((id) => String(id).trim()).filter(Boolean);
  } else if (typeof body?.docId === "string" && body.docId.trim().length > 0) {
    docIds = [body.docId.trim()];
  } else {
    docIds = [];
  }

  if (config.allowedDatasets && !config.allowedDatasets.includes(ds)) return err("PERMISSION_DENIED", "Permission denied");
  let allowed = false;
  try { allowed = await authorize(config, req, {
    dataset: ds,
    type: "*",
    action: "doc.read",
  }); } catch { allowed = false; }
  if (!allowed) {
    return err("PERMISSION_DENIED", "Permission denied", {});
  }

  if (config.checkCapabilities && !await config.checkCapabilities(req, ["content.docs", "content.realtime"])) return err("CONTENTFN_UNAVAILABLE", "ContentFn preview capabilities are unavailable");
  const result = mintPreviewToken(
    { secret: config.previewSecret, ttlSec: config.ttlSec },
    ds,
    docIds
  );
  return ok(result);
}
/**
 * Preview pane: iframe with preview URL + token; updates on draft changes (realtime or refresh callback).
 */

import { useState, useEffect, useRef, useCallback } from "react";
import { subscribeToDoc } from "../../realtime/subscribe.js";

const PREVIEW_TOKEN_PARAM = "cmsfn_preview_token";

export interface PreviewPaneProps {
  /** When false or missing, show deterministic disabled UI. */
  previewEnabled?: boolean;
  targetOrigin: string;
  resolveUrl: (doc: unknown) => string;
  /** CmsFn server URL for POST /cmsfn/preview/token. */
  cmsfnApiUrl?: string;
  dataset: string;
  /** Current doc (draft) for resolveUrl and token scope. */
  doc: unknown;
  /** Optional WebSocket URL for ContentFn realtime; when set, preview refreshes on events. */
  realtimeUrl?: string;
  /** When set, preview will refresh when this is called (e.g. after save). */
  refreshTrigger?: number;
}

async function fetchPreviewToken(
  cmsfnApiUrl: string,
  dataset: string,
  docId: string
): Promise<{ token: string; expiresAt: string } | null> {
  const base = cmsfnApiUrl.replace(/\/+$/, "");
  const res = await fetch(`${base}/cmsfn/preview/token`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ dataset, docId }),
  });
  const data = await res.json();
  if (!res.ok || !data?.ok) return null;
  const r = data.result as { token?: string; expiresAt?: string };
  return r?.token && r?.expiresAt ? { token: r.token, expiresAt: r.expiresAt } : null;
}

function buildPreviewUrl(baseUrl: string, token: string): string {
  const u = new URL(baseUrl);
  u.searchParams.set(PREVIEW_TOKEN_PARAM, token);
  return u.toString();
}

export function PreviewPane({
  previewEnabled,
  targetOrigin,
  resolveUrl,
  cmsfnApiUrl,
  dataset,
  doc,
  realtimeUrl,
  refreshTrigger,
}: PreviewPaneProps) {
  const [token, setToken] = useState<string | null>(null);
  const [tokenError, setTokenError] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const docId = (doc as { _id?: string })?._id;

  const refresh = useCallback(() => {
    setRefreshKey((k) => k + 1);
  }, []);

  // Request token when doc or config changes
  useEffect(() => {
    if (!previewEnabled || !cmsfnApiUrl || !docId) {
      setToken(null);
      setTokenError(false);
      return;
    }
    let cancelled = false;
    fetchPreviewToken(cmsfnApiUrl, dataset, docId).then((t) => {
      if (!cancelled) {
        setToken(t?.token ?? null);
        setTokenError(!t);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [previewEnabled, cmsfnApiUrl, dataset, docId]);

  // Realtime subscription: on event, refresh preview
  useEffect(() => {
    if (!docId || !realtimeUrl) return;
    const unsub = subscribeToDoc({
      realtimeUrl,
      dataset,
      docId,
      onUpdate: refresh,
    });
    return unsub;
  }, [realtimeUrl, dataset, docId, refresh]);

  // When parent signals refresh (e.g. after save)
  const prevTrigger = useRef(refreshTrigger);
  useEffect(() => {
    if (refreshTrigger != null && refreshTrigger !== prevTrigger.current) {
      prevTrigger.current = refreshTrigger;
      refresh();
    }
  }, [refreshTrigger, refresh]);

  if (!previewEnabled) {
    return (
      <div data-preview-pane data-preview-disabled="true">
        <p>Preview is not configured.</p>
      </div>
    );
  }

  if (!cmsfnApiUrl || !docId) {
    return (
      <div data-preview-pane data-preview-disabled="true">
        <p>Preview requires CmsFn server URL and an open document.</p>
      </div>
    );
  }

  if (tokenError || !token) {
    return (
      <div data-preview-pane data-preview-error="true">
        <p>{tokenError ? "Failed to load preview token." : "Loading preview…"}</p>
      </div>
    );
  }

  const baseUrl = resolveUrl(doc);
  const previewUrl = buildPreviewUrl(baseUrl, token);

  return (
    <div data-preview-pane data-preview-visible="true">
      <iframe
        key={refreshKey}
        data-preview-iframe
        title="Preview"
        src={previewUrl}
        referrerPolicy="no-referrer"
        style={{ width: "100%", height: "100%", border: "none" }}
      />
    </div>
  );
}
/**
 * Subscribe to ContentFn realtime events for a doc; on event, call callback (debounced).
 * When realtimeUrl is not configured, returns a no-op unsubscribe (e.g. refresh-on-save only).
 */

const DEFAULT_DEBOUNCE_MS = 500;

export interface SubscribeConfig {
  /** WebSocket URL for ContentFn realtime (e.g. ws://host/contentfn/realtime). When absent, no subscription. */
  realtimeUrl?: string;
  dataset: string;
  docId: string;
  /** Called when a doc event is received; debounced. */
  onUpdate: () => void;
  debounceMs?: number;
}

/**
 * Subscribe to draft/doc changes for the given dataset and docId.
 * Returns unsubscribe function.
 */
export function subscribeToDoc(config: SubscribeConfig): () => void {
  const { realtimeUrl, dataset, docId, onUpdate, debounceMs = DEFAULT_DEBOUNCE_MS } = config;

  if (!realtimeUrl || typeof WebSocket === "undefined") {
    return () => {};
  }

  let ws: WebSocket | null = null;
  let debounceTimer: ReturnType<typeof setTimeout> | null = null;
  let closed = false;

  function scheduleUpdate(): void {
    if (closed) return;
    if (debounceTimer) clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
      debounceTimer = null;
      onUpdate();
    }, debounceMs);
  }

  try {
    ws = new WebSocket(realtimeUrl);
    ws.onmessage = (event) => {
      try {
        const msg = typeof event.data === "string" ? JSON.parse(event.data) : null;
        const eventDocId = msg?.document?._id;
        const match = msg?.type === "event" && msg?.dataset === dataset && (!eventDocId || eventDocId === docId || eventDocId === docId.replace(/^drafts\./, "") || docId === `drafts.${eventDocId}`);
        if (match) {
          scheduleUpdate();
        }
      } catch {
        // ignore parse errors
      }
    };
    ws.onopen = () => {
      if (closed || !ws) return;
      ws.send(JSON.stringify({ type: "subscribe", dataset, docId }));
    };
  } catch {
    return () => {};
  }

  return () => {
    closed = true;
    if (debounceTimer) clearTimeout(debounceTimer);
    if (ws) {
      try {
        ws.send(JSON.stringify({ type: "unsubscribe", dataset, docId }));
        ws.close();
      } catch {
        // ignore
      }
      ws = null;
    }
  };
}

export interface SubscribeDatasetConfig {
  realtimeUrl?: string;
  dataset: string;
  /** Called for any doc event in the dataset (patch, publish, etc.). */
  onEvent: (event: { type: string; dataset?: string; docId?: string }) => void;
}

/**
 * Subscribe to all doc events in a dataset (for list refresh and remote-changed).
 * Returns unsubscribe function.
 */
export function subscribeToDataset(config: SubscribeDatasetConfig): () => void {
  const { realtimeUrl, dataset, onEvent } = config;

  if (!realtimeUrl || typeof WebSocket === "undefined") {
    return () => {};
  }

  let ws: WebSocket | null = null;
  let closed = false;

  try {
    ws = new WebSocket(realtimeUrl);
    ws.onmessage = (ev) => {
      try {
        const msg = typeof ev.data === "string" ? JSON.parse(ev.data) : null;
        if (msg?.type === "event" && msg?.dataset === dataset) {
          const docId = msg?.document?._id ?? msg?.docId;
          onEvent({ type: "event", dataset: msg.dataset, docId });
        }
      } catch {
        // ignore
      }
    };
    ws.onopen = () => {
      if (closed || !ws) return;
      ws.send(JSON.stringify({ type: "subscribe", dataset }));
    };
  } catch {
    return () => {};
  }

  return () => {
    closed = true;
    if (ws) {
      try {
        ws.send(JSON.stringify({ type: "unsubscribe", dataset }));
        ws.close();
      } catch {
        // ignore
      }
      ws = null;
    }
  };
}
