export function parseClientMessage(raw: string): RealtimeClientMessage | null {
  try {
    const msg = JSON.parse(raw);
    if (typeof msg !== "object" || msg === null) return null;
    if (msg.type === "subscribe" || msg.type === "unsubscribe") {
