### MEDIA-001: Media library upload/browse/insert asset refs

**Priority**: P0  
**Statement**: The Studio MUST provide a media library that uploads and browses ContentFn assets and inserts canonical asset references into documents.  
**Rationale**: Asset management is core CMS functionality.  
**Acceptance criteria**:
- Upload uses ContentFn assets API and enforces upload size limits.
- Browse lists assets deterministically (order documented).
- Insert creates `{ "_type":"asset", "_ref":"<id>", "assetType":"image|file" }`.
**Test vectors**: TV-MEDIA-UPLOAD-001, TV-MEDIA-BROWSE-001, TV-MEDIA-INSERT-001, TV-LIMIT-UPLOAD-001  
**Notes**: Image transforms are undefined unless configured.

---

### REF-001: Reference picker UX with deterministic search/browse

**Priority**: P0  
**Statement**: Reference fields MUST be editable via a reference picker that queries ContentFn deterministically and shows bounded previews of candidate documents.  
**Rationale**: References are essential for content graphs.  
**Acceptance criteria**:
- Picker lists candidates by type and filter.
- Picker uses deterministic ordering and pagination.
- Selecting creates a canonical reference object.
**Test vectors**: TV-REF-PICKER-001, TV-REF-PICKER-002  
**Notes**: The `match` operator support depends on ContentFn SEARCH-001.

---

/**
 * Media library: upload asset, browse (deterministic order), select to insert ref.
 */

import { useState, useEffect, useCallback } from "react";
import { uploadAssetWithLimit } from "../../media/upload.js";
import { browseAssets } from "../../media/browse.js";
import { buildAssetRef } from "../../media/insertAssetRef.js";
import type { CanonicalAssetRef } from "../../media/insertAssetRef.js";
import type { AssetListItem } from "../../contentfn/client.js";

export interface MediaLibraryPaneProps {
  baseUrl: string;
  dataset: string;
  maxUploadBytes?: number;
  /** When user selects an asset, call with canonical asset ref. */
  onSelectAsset?: (ref: CanonicalAssetRef) => void;
}

function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const dataUrl = reader.result as string;
      const base64 = dataUrl.includes(",") ? dataUrl.split(",")[1] : dataUrl;
      resolve(base64 ?? "");
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

export function MediaLibraryPane({
  baseUrl,
  dataset,
  maxUploadBytes,
  onSelectAsset,
}: MediaLibraryPaneProps) {
  const [assets, setAssets] = useState<AssetListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploadError, setUploadError] = useState<string | null>(null);

  const loadAssets = useCallback(async () => {
    if (!dataset) return;
    setLoading(true);
    setError(null);
    const result = await browseAssets({ baseUrl, dataset });
    setLoading(false);
    if (result.ok) {
      setAssets(result.assets);
    } else {
      setError(result.message);
    }
  }, [baseUrl, dataset]);

  useEffect(() => {
    loadAssets();
  }, [loadAssets]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !dataset) return;
    e.target.value = "";
    setUploading(true);
    setUploadError(null);
    const base64 = await fileToBase64(file);
    const result = await uploadAssetWithLimit(
      { baseUrl, maxUploadBytes },
      {
        dataset,
        filename: file.name,
        contentType: file.type || "application/octet-stream",
        bytesBase64: base64,
      }
    );
    setUploading(false);
    if (result.ok) {
      await loadAssets();
    } else {
      setUploadError(result.message);
    }
  };

  const handleSelect = (asset: AssetListItem) => {
    const ref = buildAssetRef(asset.assetId, asset.contentType);
    onSelectAsset?.(ref);
  };

  return (
    <div data-media-library-pane>
      <div data-media-upload>
        <input
          type="file"
          data-media-upload-input
          disabled={uploading || !dataset}
          onChange={handleFileChange}
          aria-label="Upload file"
        />
        {uploadError && (
          <p data-media-upload-error role="alert">
            {uploadError}
          </p>
        )}
      </div>
      {error && (
        <p data-media-browse-error role="alert">
          {error}
        </p>
      )}
      {loading ? (
        <p data-media-loading>Loading…</p>
      ) : (
        <ul data-media-list role="list">
          {assets.map((asset) => (
            <li key={asset.assetId} data-media-item data-asset-id={asset.assetId}>
              <button
                type="button"
                data-media-select
                onClick={() => handleSelect(asset)}
                disabled={!onSelectAsset}
              >
                <span data-media-filename>{asset.filename}</span>
                <span data-media-id>{asset.assetId}</span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
/**
 * Reference picker dialog: list candidates via CFQL (type-scoped, deterministic), bounded preview, select → canonical ref.
 * When role lacks doc.read for candidate type, shows deterministic "no access" (data-ref-picker-denied).
 */

import { useState, useEffect, useCallback } from "react";
import type { ContentfnDocument } from "@contentfn/core";
import { queryCandidates } from "../../../references/queryCandidates.js";

export interface ReferencePickerDialogProps {
  baseUrl: string;
  dataset: string;
  /** Allowed document types (reference field's `to`). */
  allowedTypes: string[];
  /** When false, show "no access" state (deterministic for TV-REF-PICKER-002). */
  hasDocRead?: boolean;
  onSelect: (ref: { _type: "reference"; _ref: string }) => void;
  onClose: () => void;
}

const PREVIEW_PROJECTION = { fields: ["_id", "_type", "title", "name"] };
const PAGE_LIMIT = 20;

export function ReferencePickerDialog({
  baseUrl,
  dataset,
  allowedTypes,
  hasDocRead = true,
  onSelect,
  onClose,
}: ReferencePickerDialogProps) {
  const [candidates, setCandidates] = useState<ContentfnDocument[]>([]);
  const [nextCursor, setNextCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadPage = useCallback(
    async (cursor?: string | null) => {
      if (!dataset || allowedTypes.length === 0) return;
      setLoading(true);
      setError(null);
      const envelope = await queryCandidates({
        baseUrl,
        dataset,
        types: allowedTypes,
        projection: PREVIEW_PROJECTION,
        limit: PAGE_LIMIT,
        cursor: cursor ?? null,
      });
      setLoading(false);
      if (envelope.ok) {
        if (cursor) {
          setCandidates((prev) => [...prev, ...envelope.result.data]);
        } else {
          setCandidates(envelope.result.data);
        }
        setNextCursor(envelope.result.nextCursor);
      } else {
        setError(envelope.error.message);
        if (cursor == null) {
          setCandidates([]);
          setNextCursor(null);
        }
      }
    },
    [baseUrl, dataset, allowedTypes]
  );

  useEffect(() => {
    if (hasDocRead) loadPage();
  }, [hasDocRead, loadPage]);

  const handleSelect = (doc: ContentfnDocument) => {
    const id = (doc as { _id?: string })._id;
    if (id) onSelect({ _type: "reference", _ref: id });
    onClose();
  };

  if (!hasDocRead) {
    return (
      <div role="dialog" aria-modal="true" data-ref-picker data-ref-picker-denied>
        <p data-ref-picker-denied-message>No access</p>
        <button type="button" onClick={onClose} data-ref-picker-close>
          Close
        </button>
      </div>
    );
  }

  return (
    <div role="dialog" aria-modal="true" data-ref-picker>
      <div data-ref-picker-header>
        <h2 data-ref-picker-title>Choose reference</h2>
        <button type="button" onClick={onClose} data-ref-picker-close aria-label="Close">
          Close
        </button>
      </div>
      {error && <p data-ref-picker-error>{error}</p>}
      {loading && candidates.length === 0 && <p data-ref-picker-loading>Loading…</p>}
      <ul data-ref-picker-list>
        {candidates.map((doc) => {
          const d = doc as Record<string, unknown>;
          const id = (d._id as string) ?? "";
          const label = (d.title as string) ?? (d.name as string) ?? id ?? "(no id)";
          return (
            <li key={id} data-ref-picker-item data-ref-picker-item-id={id}>
              <button type="button" onClick={() => handleSelect(doc)} data-ref-picker-select>
                {label}
              </button>
            </li>
          );
        })}
      </ul>
      {nextCursor && (
        <button
          type="button"
          onClick={() => loadPage(nextCursor)}
          disabled={loading}
          data-ref-picker-load-more
        >
          Load more
        </button>
      )}
    </div>
  );
}

