/**
 * CmsFn server API types (SPEC.md) — canonical I/O shapes for endpoints.
 */

import type { CmsfnEnvelope } from "../envelope.js";
import type { CmsfnRole } from "../roles/types.js";
import type { CmsfnRelease, CmsfnReleasePublishResult } from "../releases/types.js";

export interface CmsfnStatusResult {
  serverTime: string; // ISO 8601
  capabilities: string[];
  datasets: string[];
}

export interface CmsfnPreviewTokenResult {
  /** Trusted target origin; required by version-2 preview consumers. */
  audience?: string;
  token: string;
  expiresAt: string; // ISO 8601
  dataset: string;
  docIds: string[];
}

export interface CmsfnAuditEvent {
  eventId: string;
  dataset: string;
  type: string;
  timestamp: string; // ISO 8601
  actor?: { subject?: string };
  /** Authoritative audit targets; no document body or inferred type. */
  targetIds?: string[];
  document?: { _id: string; _type: string; _rev?: string };
  diff?: { changedPaths?: string[] };
}

export interface CmsfnWebhookDeliveryStatus {
  webhookId: string;
  dataset: string;
  url: string | null;
  eventId: string;
  attempt: number;
  status: "pending" | "processing" | "delivered" | "failed";
  lastError?: string;
  updatedAt: string | null; // Legacy history may have no known timestamp.
  timestampKnown?: boolean;
}

export interface CmsfnServerAPI {
  status: () => Promise<CmsfnEnvelope<CmsfnStatusResult>>;
  roles: {
    list: (input: { dataset: string }) => Promise<CmsfnEnvelope<{ roles: CmsfnRole[] }>>;
    upsert: (input: { role: CmsfnRole }) => Promise<CmsfnEnvelope<{ role: CmsfnRole }>>;
    delete: (input: { roleId: string }) => Promise<CmsfnEnvelope<Record<string, never>>>;
  };
  preview: {
    token: (input: { dataset: string; docIds: string[] }) => Promise<CmsfnEnvelope<CmsfnPreviewTokenResult>>;
  };
  releases: {
    create: (input: { dataset: string; name: string; publishAt?: string | null }) => Promise<CmsfnEnvelope<{ releaseId: string }>>;
    list: (input: { dataset: string }) => Promise<CmsfnEnvelope<{ releases: CmsfnRelease[]; schedulingEnabled?: boolean }>>;
    add: (input: { dataset: string; releaseId: string; docId: string }) => Promise<CmsfnEnvelope<Record<string, never>>>;
    publish: (input: { dataset: string; releaseId: string }) => Promise<CmsfnEnvelope<CmsfnReleasePublishResult>>;
  };
  ops: {
    export: (input: { dataset: string }) => Promise<CmsfnEnvelope<{ artifact: unknown }>>;
    import: (input: { dataset: string; artifact: unknown }) => Promise<CmsfnEnvelope<Record<string, never>>>;
  };
  audit: {
    events: (input: { dataset: string; limit?: number; cursor?: string | null }) => Promise<CmsfnEnvelope<{ events: CmsfnAuditEvent[]; nextCursor: string | null }>>;
    webhooks: (input: { dataset: string; limit?: number; cursor?: string | null }) => Promise<CmsfnEnvelope<{ deliveries: CmsfnWebhookDeliveryStatus[]; nextCursor: string | null }>>;
  };
}
/** Server-authorized, published-only reference candidates. */
import type { IncomingMessage } from 'http';
import { err, parseReferenceInput, projectReferencePage, referenceQuery, type CmsfnReferencePage, type CmsfnEnvelope } from 'cmsfn';
import { authorize, type AuthorizeConfig } from '../auth/authorize.js';
import type { CapabilityGateConfig } from '../contentfn/statusClient.js';
import { contentfnRequest } from '../contentfn/response.js';
import { readJsonObject } from './jsonBody.js';
export interface ReferenceHandlerConfig extends AuthorizeConfig, CapabilityGateConfig {
  allowedDatasets: readonly string[]; contentfnBaseUrl: string;
  contentfnReferenceHeaders?: (request: IncomingMessage) => NonNullable<RequestInit['headers']> | Promise<NonNullable<RequestInit['headers']>>;
}
export async function handleReferenceQuery(config: ReferenceHandlerConfig, request: IncomingMessage): Promise<CmsfnEnvelope<CmsfnReferencePage>> {
  const body = await readJsonObject(request, 96 * 1024); if (!body.ok) return body;
  const input = parseReferenceInput(body.result); if (!input) return err('VALIDATION_FAILED', 'Invalid reference query');
  try {
    if (!config.allowedDatasets.includes(input.dataset)) return err('PERMISSION_DENIED', 'No access to references.');
    for (const type of input.types) if (!await authorize(config, request, { dataset: input.dataset, type, action: 'doc.read' })) return err('PERMISSION_DENIED', 'No access to references.');
  } catch { return err('PERMISSION_DENIED', 'No access to references.'); }
  try {
    if (config.checkCapabilities && !await config.checkCapabilities(request, ['content.docs'])) return err('CONTENTFN_UNAVAILABLE', 'Reference queries are unavailable.');
    const headers = await config.contentfnReferenceHeaders?.(request);
    const query = referenceQuery(input);
    const deadline = Date.now() + 10_000;
    for (let limit = input.limit ?? 20;; limit = Math.max(1, Math.floor(limit / 2))) {
      let timer: ReturnType<typeof setTimeout> | undefined;
      const remaining = Math.max(1, deadline - Date.now());
      const response = await Promise.race([
        contentfnRequest(config.contentfnBaseUrl, '/contentfn/query', { ...query, limit }, value => projectReferencePage(value, { ...input, limit }), { headers, maxResponseBytes: 2 * 1024 * 1024, timeoutMs: remaining, redirect: 'error' }),
        new Promise<CmsfnEnvelope<CmsfnReferencePage>>(resolve => { timer = setTimeout(() => resolve(err('CONTENTFN_UNAVAILABLE', 'Reference query timed out.')), remaining); }),
      ]).finally(() => clearTimeout(timer));
      if (response.ok) return response;
      if (response.error.details.failureKind === 'response-too-large' && limit > 1 && Date.now() < deadline) continue;
      return err(response.error.code, response.error.code === 'PERMISSION_DENIED' || response.error.code === 'AUTH_REQUIRED' ? 'No access to references.' : 'Reference query could not be completed.', response.error.details.failureKind === 'response-too-large' ? { reason: 'REFERENCE_PREVIEW_TOO_LARGE' } : {});
    }
  } catch { return err('CONTENTFN_UNAVAILABLE', 'Reference query could not be configured.'); }
}

